const config = $('Validate Config4').first().json;
const plans = {
  accounts: [['chartofaccounts','chartofaccounts']],
  customers: [['contacts','contacts']],
  vendors: [['contacts','contacts']],
  items: [['chartofaccounts','chartofaccounts'],['items','items']],
  invoices: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['items','items'],['invoices','invoices'],['settings/taxes','taxes']],
  invoice_payments: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['invoices','invoices'],['customerpayments','customerpayments']],
  bills: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['items','items'],['bills','bills'],['settings/taxes','taxes']],
  bill_payments: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['bills','bills'],['vendorpayments','vendorpayments']],
  expenses: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['items','items'],['expenses','expenses'],['settings/taxes','taxes']],
  expense_refunds: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['expenses','expenses'],['banktransactions','banktransactions']],
  credit_card_repayments: [['chartofaccounts','chartofaccounts'],['expenses','expenses'],['banktransactions','banktransactions']],
  bank_transactions: [['chartofaccounts','chartofaccounts'],['customerpayments','customerpayments'],['vendorpayments','vendorpayments'],['expenses','expenses'],['banktransactions','banktransactions']],
  journals: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['journals','journals']],
  overall_audit: [['chartofaccounts','chartofaccounts'],['contacts','contacts'],['items','items'],['invoices','invoices'],['customerpayments','customerpayments'],['bills','bills'],['vendorpayments','vendorpayments'],['expenses','expenses'],['banktransactions','banktransactions'],['journals','journals'],['creditnotes','creditnotes'],['vendorcredits','vendorcredits'],['salesreceipts','salesreceipts']]
};
const selected = plans[config.phase] || [];
if (!selected.length) throw new Error('No Zoho snapshot plan for phase: ' + config.phase);

// Master snapshots are required in every phase so all four master ID maps can
// be rebuilt without manually maintaining hundreds of overrides.
const masterSnapshots = [
  ['chartofaccounts', 'chartofaccounts'],
  ['contacts', 'contacts'],
  ['items', 'items']
];
const combined = [];
const seen = new Set();
for (const pair of [...masterSnapshots, ...selected]) {
  const identity = pair[0] + '|' + pair[1];
  if (seen.has(identity)) continue;
  seen.add(identity);
  combined.push(pair);
}

return combined.map(([path,key]) => ({ json: {
  snapshot_key: key,
  url: config.zoho_api_base + '/' + path,
  organization_id: config.zoho_organization_id,
  page_size: config.zoho_page_size
}}));

const config = $('Validate Config4').first().json;
const all = $('Strict Payload Builder4').all().map(i => i.json);
const quarantined = all.filter(row => row.outcome === 'quarantine');
const readyCount = all.filter(row => row.outcome === 'ready').length;
const dryRun = config.dry_run === true || String(config.dry_run).toLowerCase() === 'true';
const strictBlocked = Boolean(config.stop_on_any_unmapped_value && quarantined.length > 0);
const maxLive = Math.max(1, Number(config.max_live_records_per_run || 1000));
const quotaBlocked = !dryRun && readyCount > maxLive;
const liveBlocked = strictBlocked || quotaBlocked;
return $input.all().map(item => ({ json: {
  ...item.json,
  dry_run: dryRun,
  live_blocked: liveBlocked,
  quota_blocked: quotaBlocked,
  ready_count: readyCount,
  max_live_records_per_run: maxLive,
  route_to_summary: dryRun || liveBlocked
}}));

const rows = $('Normalize Zoho Result4').all().map(item => item.json);
const counts = rows.reduce((acc, row) => {
  acc[row.outcome || 'unknown'] = (acc[row.outcome || 'unknown'] || 0) + 1;
  return acc;
}, {});
return [{ json: {
  phase: rows[0]?.phase || 'unknown',
  counts,
  total: rows.length,
  failed_sample: rows.filter(row => row.outcome === 'failed').slice(0, 50)
} }];

const c = { ...$json };
const errors = [];
const phases = ["accounts","customers","vendors","items","invoices","invoice_payments","bills","bill_payments","expenses","expense_refunds","credit_card_repayments","bank_transactions","journals","overall_audit"];
const modes = ['all','year','cutover'];
if (!c.qbo_realm_id || c.qbo_realm_id.startsWith('REPLACE_')) errors.push('Set qbo_realm_id');
if (!c.qbo_client_id || c.qbo_client_id.startsWith('PASTE_')) errors.push('Set qbo_client_id');
if (!c.qbo_client_secret || c.qbo_client_secret.startsWith('PASTE_')) errors.push('Set qbo_client_secret');
if (!c.qbo_refresh_token || c.qbo_refresh_token.startsWith('PASTE_')) errors.push('Set qbo_refresh_token');
if (!c.zoho_organization_id || c.zoho_organization_id.startsWith('REPLACE_')) errors.push('Set exactly one zoho_organization_id');
if (!phases.includes(c.phase)) errors.push('Invalid phase');
if (!modes.includes(c.migration_mode)) errors.push('Invalid migration_mode');
if (c.migration_mode === 'year') {
  const y = Number(c.year);
  if (!Number.isInteger(y) || y < 1900 || y > 2200) errors.push('Set a valid four-digit year');
  else {
    c.start_date = String(y) + '-01-01';
    c.end_date = String(y) + '-12-31';
  }
}
if (c.migration_mode === 'cutover') c.start_date = c.cutover_date;
if (c.migration_mode !== 'all' && (!/^\d{4}-\d{2}-\d{2}$/.test(c.start_date) || !/^\d{4}-\d{2}-\d{2}$/.test(c.end_date))) errors.push('Use YYYY-MM-DD dates');
if (c.migration_mode !== 'all' && c.start_date > c.end_date) errors.push('start_date must be <= end_date');
if (c.phase === 'overall_audit' && c.dry_run !== true) errors.push('overall_audit must use dry_run=true');
if (!c.dry_run && Object.values(c.custom_field_ids || {}).some(v => !v)) errors.push('Live mode requires all QBO ID custom-field IDs');
if (c.repair_existing_only !== true && c.repair_existing_only !== false) errors.push('repair_existing_only must be true or false');
if (c.strict_phase_ownership !== true) errors.push('strict_phase_ownership must be true');
if (Number(c.zoho_write_delay_seconds || 0) < 1) errors.push('zoho_write_delay_seconds must be at least 1');
return [{ json: { ...c, config_valid: errors.length === 0, config_errors: errors } }];

const session = $json;
const accessToken = String(session.qbo_access_token || '').trim();
if (!accessToken) throw new Error('QBO access token missing. Run from Manual Trigger.');

const config = { ...session };
delete config.qbo_access_token;
delete config.qbo_refresh_token;
delete config.qbo_refresh_token_next;

const phaseEntities = {
  accounts: ['Account'],
  customers: ['Customer'],
  vendors: ['Vendor'],
  items: ['Item'],
  invoices: ['Invoice'],
  invoice_payments: ['Payment'],
  bills: ['Bill'],
  bill_payments: ['BillPayment'],
  expenses: ['Purchase'],
  expense_refunds: ['Deposit', 'Purchase'],
  credit_card_repayments: ['Transfer', 'Purchase', 'Deposit'],
  bank_transactions: ['Transfer', 'Deposit', 'Purchase'],
  journals: ['JournalEntry'],
  overall_audit: ['Account','Customer','Vendor','Item','Invoice','Payment','Bill','BillPayment','Purchase','Transfer','Deposit','JournalEntry','CreditMemo','VendorCredit','SalesReceipt','RefundReceipt']
};

const masters = new Set(['Account', 'Customer', 'Vendor', 'Item']);
const dateWhere = config.migration_mode === 'all'
  ? ''
  : ` WHERE TxnDate >= '${config.start_date}' AND TxnDate <= '${config.end_date}'`;

// Always fetch the four master entities once. Attach Strict ID Maps uses
// them to build complete Account/Customer/Vendor/Item maps for every phase.
const mappingMasters = ['Account', 'Customer', 'Vendor', 'Item'];
const selectedEntities = [...new Set([
  ...mappingMasters,
  ...(phaseEntities[config.phase] || [])
])];

return selectedEntities.map((entity) => ({
  json: {
    config,
    qbo_access_token: accessToken,
    source_entity: entity,
    query_prefix: `SELECT * FROM ${entity}${masters.has(entity) ? '' : dateWhere}`
  }
}));

const rawConfig = $('Validate Config4').first().json;
const config = { ...rawConfig };
delete config.qbo_refresh_token;

const ignored = new Set(['startPosition','maxResults','totalCount']);
const out = [];
for (const page of $input.all()) {
  const qr = page.json.QueryResponse || {};
  for (const [entity, records] of Object.entries(qr)) {
    if (ignored.has(entity) || !Array.isArray(records)) continue;
    for (const source of records) out.push({ json: { config, source_entity: entity, source } });
  }
}
return out;

/*
 * Build strict QuickBooks-ID -> Zoho-ID maps and a complete idempotency snapshot.
 * Mode: Run Once for All Items
 */
const incoming = $input.all().map((item) => item?.json || {});
const clean = (value) => String(value ?? '').trim();

const sourceRows = incoming.filter((row) =>
  row?.source_entity && row?.source && typeof row.source === 'object' && !Array.isArray(row.source)
);

if (!sourceRows.length) {
  return [{ json: {
    outcome: 'quarantine',
    source_entity: 'Unknown',
    source_id: '',
    error_code: 'NO_QBO_SOURCE_ROWS',
    error_message: 'No QuickBooks records reached Attach Strict ID Maps1. Run the complete workflow from Manual Trigger.',
    received_item_count: incoming.length,
    occurred_at: new Date().toISOString()
  }}];
}

const config = sourceRows.find((row) => row.config)?.config || {};
const pages = (...keys) => {
  const records = [];
  for (const row of incoming) {
    for (const key of keys) {
      if (Array.isArray(row?.[key])) records.push(...row[key]);
      if (Array.isArray(row?.body?.[key])) records.push(...row.body[key]);
    }
  }
  return records.filter((record) => record && typeof record === 'object');
};

const accounts = pages('chartofaccounts', 'accounts');
const contacts = pages('contacts');
const items = pages('items');
const invoices = pages('invoices');
const bills = pages('bills');
const customerPayments = pages('customerpayments', 'customer_payments');
const vendorPayments = pages('vendorpayments', 'vendor_payments');
const taxes = pages('taxes');
const expenses = pages('expenses');
const bankTransactions = pages('banktransactions', 'bank_transactions');
const journals = pages('journals');
const creditNotes = pages('creditnotes', 'credit_notes');
const vendorCredits = pages('vendorcredits', 'vendor_credits');
const salesReceipts = pages('salesreceipts', 'sales_receipts');

const fieldValue = (record, wantedFieldId) => {
  const wanted = clean(wantedFieldId);
  if (!record || !wanted) return '';
  const fields = Array.isArray(record.custom_fields) ? [...record.custom_fields] : [];
  if (record.custom_field_hash && typeof record.custom_field_hash === 'object') {
    for (const [api_name, value] of Object.entries(record.custom_field_hash)) fields.push({ api_name, value });
  }
  const match = fields.find((field) => [
    field?.customfield_id, field?.custom_field_id, field?.field_id, field?.api_name
  ].map(clean).includes(wanted));
  return clean(match?.value);
};

const applyOverrides = (target, overrides) => {
  for (const [sourceId, targetId] of Object.entries(overrides || {})) {
    if (clean(sourceId) && clean(targetId)) target[clean(sourceId)] = clean(targetId);
  }
};

const mapByField = (records, fieldId, idKey) => {
  const result = {};
  for (const record of records) {
    const sourceId = fieldValue(record, fieldId);
    const targetId = clean(record?.[idKey]);
    if (sourceId && targetId) result[sourceId] = targetId;
  }
  return result;
};

const findQboKeys = (value) => {
  const keys = [];
  const text = clean(value);
  const expression = /QBO:([A-Za-z_]+):([A-Za-z0-9._-]+)/g;
  let match;
  while ((match = expression.exec(text)) !== null) keys.push('QBO:' + match[1] + ':' + match[2]);
  return keys;
};

const accountByQbo = mapByField(accounts, config.custom_field_ids?.account_qbo_id, 'account_id');
for (const account of accounts) {
  const targetId = clean(account.account_id);
  const descriptionMatch = clean(account.description).match(/QBO Account ID:\s*([A-Za-z0-9._-]+)/i);
  const sourceId = fieldValue(account, config.custom_field_ids?.account_qbo_id) || clean(descriptionMatch?.[1]);
  if (sourceId && targetId) accountByQbo[sourceId] = targetId;
}
applyOverrides(accountByQbo, config.approved_account_overrides);

const normalizeName = (value) => clean(value).toLowerCase().replace(/\s+/g, ' ');
const expectedAccountName = (qb) => {
  const qualified = clean(qb?.FullyQualifiedName);
  return qb?.SubAccount && config.use_qualified_account_names && qualified
    ? qualified.replace(/\s*:\s*/g, ' - ')
    : clean(qb?.Name);
};

const qboAccountTypeToZoho = (qb) => {
  if (clean(qb?.AccountType) === 'Bank') {
    return clean(qb?.AccountSubType) === 'CashOnHand' ? 'cash' : 'bank';
  }
  if (
    clean(qb?.AccountType) === 'Other Current Asset' &&
    clean(qb?.AccountSubType) === 'UndepositedFunds'
  ) return 'cash';
  const types = {
    'Accounts Receivable': 'accounts_receivable',
    'Other Current Asset': 'other_current_asset',
    'Fixed Asset': 'fixed_asset',
    'Other Asset': 'other_asset',
    'Accounts Payable': 'accounts_payable',
    'Credit Card': 'credit_card',
    'Other Current Liability': 'other_current_liability',
    'Long Term Liability': 'long_term_liability',
    'Equity': 'equity',
    'Income': 'income',
    'Other Income': 'other_income',
    'Expense': 'expense',
    'Cost of Goods Sold': 'cost_of_goods_sold',
    'Other Expense': 'other_expense'
  };
  return clean(types[clean(qb?.AccountType)]).toLowerCase();
};

// Fill missing account IDs by exact unique name + compatible account type.
// Parent IDs are also checked for subaccounts. Existing custom-field,
// description and approved override mappings always win.
for (let pass = 0; pass < 20; pass++) {
  let changed = false;
  for (const row of sourceRows.filter((candidate) => candidate.source_entity === 'Account')) {
    const qb = row.source || {};
    const sourceId = clean(qb.Id);
    if (!sourceId || accountByQbo[sourceId]) continue;

    const expectedName = normalizeName(expectedAccountName(qb));
    const expectedType = qboAccountTypeToZoho(qb);
    const parentId = qb.SubAccount
      ? clean(accountByQbo[clean(qb.ParentRef?.value)])
      : '';
    if (qb.SubAccount && !parentId) continue;

    const candidates = accounts.filter((account) => {
      const nameMatches = normalizeName(account.account_name) === expectedName;
      const targetType = clean(account.account_type).toLowerCase();
      const typeMatches = !expectedType || targetType === expectedType;
      const parentMatches = qb.SubAccount
        ? clean(account.parent_account_id) === parentId
        : !clean(account.parent_account_id);
      return nameMatches && typeMatches && parentMatches;
    });

    if (candidates.length === 1 && clean(candidates[0].account_id)) {
      accountByQbo[sourceId] = clean(candidates[0].account_id);
      changed = true;
    }
  }
  if (!changed) break;
}

const customerByQbo = {};
const vendorByQbo = {};
for (const contact of contacts) {
  const targetId = clean(contact.contact_id);
  if (!targetId) continue;
  const candidates = [fieldValue(contact, config.custom_field_ids?.contact_qbo_id)];
  for (const field of [contact.reference_number, contact.notes, contact.description]) {
    candidates.push(...findQboKeys(field).map((key) => key.replace(/^QBO:/, '')));
  }
  for (const candidate of candidates.filter(Boolean)) {
    if (candidate.startsWith('Customer:')) customerByQbo[clean(candidate.slice(9))] = targetId;
    else if (candidate.startsWith('Vendor:')) vendorByQbo[clean(candidate.slice(7))] = targetId;
    else {
      const type = clean(contact.contact_type).toLowerCase();
      if (type === 'customer' || type === 'both') customerByQbo[clean(candidate)] = targetId;
      if (type === 'vendor' || type === 'both') vendorByQbo[clean(candidate)] = targetId;
    }
  }
}
applyOverrides(customerByQbo, config.approved_customer_overrides);
applyOverrides(vendorByQbo, config.approved_vendor_overrides);

const contactNames = (record) => [
  record?.contact_name,
  record?.display_name,
  record?.company_name
].map(normalizeName).filter(Boolean);

const sourceContactName = (qb) => normalizeName(
  qb?.DisplayName || qb?.FullyQualifiedName || qb?.CompanyName ||
  [qb?.GivenName, qb?.MiddleName, qb?.FamilyName].filter(Boolean).join(' ')
);

for (const row of sourceRows) {
  const entity = clean(row.source_entity);
  if (entity !== 'Customer' && entity !== 'Vendor') continue;
  const qb = row.source || {};
  const sourceId = clean(qb.Id);
  const targetMap = entity === 'Customer' ? customerByQbo : vendorByQbo;
  if (!sourceId || targetMap[sourceId]) continue;

  const wantedName = sourceContactName(qb);
  if (!wantedName) continue;
  const candidates = contacts.filter((contact) => {
    const contactType = clean(contact.contact_type).toLowerCase();
    const typeMatches = entity === 'Customer'
      ? ['customer', 'both'].includes(contactType)
      : ['vendor', 'both'].includes(contactType);
    return typeMatches && contactNames(contact).includes(wantedName);
  });
  if (candidates.length === 1 && clean(candidates[0].contact_id)) {
    targetMap[sourceId] = clean(candidates[0].contact_id);
  }
}

const itemByQbo = mapByField(items, config.custom_field_ids?.item_qbo_id, 'item_id');
applyOverrides(itemByQbo, config.approved_item_overrides);

// Fill missing item IDs only when an exact normalized name has one target.
for (const row of sourceRows.filter((candidate) => candidate.source_entity === 'Item')) {
  const qb = row.source || {};
  const sourceId = clean(qb.Id);
  if (!sourceId || itemByQbo[sourceId]) continue;
  const wantedName = normalizeName(qb.Name || qb.FullyQualifiedName);
  if (!wantedName) continue;
  const candidates = items.filter((item) => normalizeName(item.item_name) === wantedName);
  if (candidates.length === 1 && clean(candidates[0].item_id)) {
    itemByQbo[sourceId] = clean(candidates[0].item_id);
  }
}
const invoiceByQbo = mapByField(invoices, config.custom_field_ids?.invoice_qbo_id, 'invoice_id');
const billByQbo = mapByField(bills, config.custom_field_ids?.bill_qbo_id, 'bill_id');
applyOverrides(invoiceByQbo, config.approved_invoice_overrides);
applyOverrides(billByQbo, config.approved_bill_overrides);

const existing = {};
const existingModule = {};
const addMap = (entity, map) => {
  for (const [sourceId, targetId] of Object.entries(map || {})) {
    if (clean(sourceId) && clean(targetId)) existing['QBO:' + entity + ':' + sourceId] = clean(targetId);
  }
};
addMap('Account', accountByQbo);
addMap('Customer', customerByQbo);
addMap('Vendor', vendorByQbo);
addMap('Item', itemByQbo);
addMap('Invoice', invoiceByQbo);
addMap('Bill', billByQbo);

const targetIdKeys = [
  'account_id', 'contact_id', 'item_id', 'invoice_id', 'bill_id', 'payment_id',
  'vendorpayment_id', 'vendor_payment_id', 'expense_id', 'bank_transaction_id',
  'transaction_id', 'journal_id', 'creditnote_id', 'vendor_credit_id', 'sales_receipt_id'
];

const targetGroups = [
  ['invoices', invoices], ['bills', bills],
  ['customerpayments', customerPayments], ['vendorpayments', vendorPayments],
  ['expenses', expenses], ['banktransactions', bankTransactions], ['journals', journals],
  ['creditnotes', creditNotes], ['vendorcredits', vendorCredits], ['salesreceipts', salesReceipts]
];

for (const [moduleName, records] of targetGroups) {
  for (const record of records) {
    const targetId = targetIdKeys.map((key) => clean(record?.[key])).find(Boolean) || '';
    if (!targetId) continue;
    const searchable = [
      record.reference_number, record.notes, record.description, record.receipt_number,
      record.invoice_number, record.bill_number, record.vendor_credit_number, record.creditnote_number
    ];
    for (const value of searchable) {
      for (const key of findQboKeys(value)) {
        existing[key] = targetId;
        existingModule[key] = moduleName;
      }
    }
  }
}

for (const invoice of invoices) {
  for (const key of findQboKeys(invoice.reference_number)) {
    if (key.startsWith('QBO:Invoice:') && clean(invoice.invoice_id)) {
      const sourceId = key.slice('QBO:Invoice:'.length);
      invoiceByQbo[sourceId] = clean(invoice.invoice_id);
      existing[key] = clean(invoice.invoice_id);
    }
  }
}
for (const bill of bills) {
  for (const key of findQboKeys(bill.reference_number)) {
    if (key.startsWith('QBO:Bill:') && clean(bill.bill_id)) {
      const sourceId = key.slice('QBO:Bill:'.length);
      billByQbo[sourceId] = clean(bill.bill_id);
      existing[key] = clean(bill.bill_id);
    }
  }
}

const accountRecordById = Object.fromEntries(accounts.map((account) => [clean(account.account_id), account]));
const accountMeta = {};
for (const [sourceId, targetId] of Object.entries(accountByQbo)) {
  const account = accountRecordById[clean(targetId)];
  if (account) accountMeta[sourceId] = {
    zoho_account_id: clean(targetId),
    zoho_account_name: clean(account.account_name),
    zoho_account_type: clean(account.account_type)
  };
}

const filteredSourceRows = sourceRows.filter((row) => {
  if (row.source_entity !== 'Account') return true;
  const qualified = clean(row.source?.FullyQualifiedName);
  const depth = qualified ? qualified.split(':').length - 1 : 0;
  return depth === Number(config.account_depth || 0);
});

return [{ json: {
  bundle_version: 2,
  config,
  source_rows: filteredSourceRows,
  maps: {
    account_by_qbo_id: accountByQbo,
    account_meta_by_qbo_id: accountMeta,
    customer_by_qbo_id: customerByQbo,
    vendor_by_qbo_id: vendorByQbo,
    item_by_qbo_id: itemByQbo,
    invoice_by_qbo_id: invoiceByQbo,
    bill_by_qbo_id: billByQbo,
    existing_by_source_key: existing,
    existing_module_by_source_key: existingModule
  },
  map_snapshot_counts: {
    accounts: accounts.length, contacts: contacts.length, items: items.length,
    invoices: invoices.length, bills: bills.length, customer_payments: customerPayments.length,
    vendor_payments: vendorPayments.length, taxes: taxes.length, expenses: expenses.length,
    bank_transactions: bankTransactions.length, journals: journals.length,
    credit_notes: creditNotes.length, vendor_credits: vendorCredits.length,
    sales_receipts: salesReceipts.length, existing_source_keys: Object.keys(existing).length,
    mapped_accounts: Object.keys(accountByQbo).length,
    mapped_customers: Object.keys(customerByQbo).length,
    mapped_vendors: Object.keys(vendorByQbo).length,
    mapped_items: Object.keys(itemByQbo).length
  }
}}];

const receivedInput = $input.all();
const input = [];
const upstreamQuarantines = [];

for (const receivedItem of receivedInput) {
  const bundle = receivedItem?.json || {};

  if (bundle.outcome === 'quarantine') {
    upstreamQuarantines.push(receivedItem);
    continue;
  }

  if (Array.isArray(bundle.source_rows)) {
    for (const sourceRow of bundle.source_rows) {
      if (!sourceRow?.source_entity || !sourceRow?.source) continue;

      input.push({
        json: {
          ...sourceRow,
          config: {
            ...(bundle.config || {}),
            ...(sourceRow.config || {}),
          },
          maps: bundle.maps || sourceRow.maps || {},
        },
      });
    }
    continue;
  }

  if (bundle.source_entity && bundle.source) {
    input.push({
      json: {
        ...bundle,
        config: { ...(bundle.config || {}) },
        maps: bundle.maps || {},
      },
    });
  }
}

if (!input.length) {
  if (upstreamQuarantines.length) return upstreamQuarantines;
  return [{
    json: {
      outcome: 'quarantine',
      source_entity: 'Unknown',
      source_id: '',
      source_doc_number: '',
      error_code: 'EMPTY_SOURCE_RECORDS',
      error_message: 'No QBO source records reached Strict Payload Builder. Run the complete workflow from Manual Trigger.',
      occurred_at: new Date().toISOString(),
    },
  }];
}
const clean = (value) => String(value ?? '').trim();
const num = (value) => Number(value ?? 0);
const round = (value, precision = 2) => {
  const factor = 10 ** precision;
  return Math.round((num(value) + Number.EPSILON) * factor) / factor;
};

const sourceKey = (entity, id) => `QBO:${entity}:${clean(id)}`;

const accountTypeMap = {
  'Accounts Receivable': 'accounts_receivable',
  'Other Current Asset': 'other_current_asset',
  'Fixed Asset': 'fixed_asset',
  'Other Asset': 'other_asset',
  'Accounts Payable': 'accounts_payable',
  'Credit Card': 'credit_card',
  'Other Current Liability': 'other_current_liability',
  'Long Term Liability': 'long_term_liability',
  'Equity': 'equity',
  'Income': 'income',
  'Other Income': 'other_income',
  'Expense': 'expense',
  'Cost of Goods Sold': 'cost_of_goods_sold',
  'Other Expense': 'other_expense'
};

const mapAccountType = (qb) => {
  if (qb.AccountType === 'Bank') {
    return qb.AccountSubType === 'CashOnHand' ? 'cash' : 'bank';
  }
  return accountTypeMap[qb.AccountType] || null;
};

const address = (value) => {
  if (!value) return undefined;
  const out = {
    attention: clean(value.Note),
    address: clean(value.Line1),
    street2: clean(value.Line2),
    city: clean(value.City),
    state: clean(value.CountrySubDivisionCode),
    zip: clean(value.PostalCode),
    country: clean(value.Country)
  };
  return Object.fromEntries(Object.entries(out).filter(([, v]) => v !== ''));
};

const compact = (value) => {
  if (Array.isArray(value)) return value.map(compact).filter((v) => v !== undefined);
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value)
        .map(([k, v]) => [k, compact(v)])
        .filter(([, v]) => v !== undefined)
    );
  }
  if (value === undefined || value === null || value === '') return undefined;
  return value;
};

const quarantine = (entity, qb, code, message, field, value, extra = {}) => ({
  json: {
    outcome: 'quarantine',
    source_entity: entity,
    source_id: clean(qb?.Id),
    source_doc_number: clean(qb?.DocNumber),
    error_code: code,
    error_message: message,
    unmapped_field: field || '',
    unmapped_value: value === undefined ? '' : clean(value),
    occurred_at: new Date().toISOString(),
    ...extra
  }
});

const ready = (config, entity, qb, endpoint, payload) => ({
  json: {
    outcome: 'ready',
    source_entity: entity,
    source_id: clean(qb.Id),
    source_doc_number: clean(qb.DocNumber),
    source_key: sourceKey(entity, qb.Id),
    endpoint: `${config.zoho_api_base || 'https://www.zohoapis.com/books/v3'}/${endpoint}`,
    organization_id: clean(config.zoho_organization_id),
    payload: compact(payload)
  }
});

const resolveId = (maps, mapName, ref) => {
  const id = clean(ref?.value ?? ref);
  return id ? clean(maps?.[mapName]?.[id]) : '';
};

const customField = (id, value) => id ? [{ customfield_id: id, value: clean(value) }] : undefined;

const paymentMode = (qb) => {
  const raw = clean(qb.PaymentMethodRef?.name || qb.PaymentType).toLowerCase();
  if (raw.includes('cash')) return 'cash';
  if (raw.includes('check') || raw.includes('cheque')) return 'check';
  if (raw.includes('credit')) return 'creditcard';
  if (raw.includes('bank') || raw.includes('ach') || raw.includes('wire')) return 'banktransfer';
  return 'others';
};

const taxIdFor = (config, taxCodeRef) => {
  const qbTaxId = clean(taxCodeRef?.value);
  if (!qbTaxId) return '';
  return clean(config.tax_map?.[qbTaxId]);
};

function buildAccount(config, maps, qb) {
  const mappedType = mapAccountType(qb);
  if (!mappedType) {
    return quarantine('Account', qb, 'UNSUPPORTED_ACCOUNT_TYPE',
      'QuickBooks account type has no reviewed Zoho mapping.', 'AccountType', qb.AccountType);
  }

  const existing = maps.existing_by_source_key?.[sourceKey('Account', qb.Id)];
  if (existing) {
    return { json: { outcome: 'skipped_existing', source_entity: 'Account', source_id: clean(qb.Id), target_id: clean(existing) } };
  }

  let parentId;
  if (qb.SubAccount) {
    parentId = resolveId(maps, 'account_by_qbo_id', qb.ParentRef);
    if (!parentId) {
      return quarantine('Account', qb, 'PARENT_ACCOUNT_UNMAPPED',
        'Create/map the parent account before this sub-account.', 'ParentRef', qb.ParentRef?.value);
    }
  }
  const qualifiedAccountName = clean(qb.FullyQualifiedName);

  const zohoAccountName =
    qb.SubAccount &&
    config.use_qualified_account_names &&
    qualifiedAccountName
      ? qualifiedAccountName.replace(/\s*:\s*/g, ' - ')
      : clean(qb.Name);

  return ready(config, 'Account', qb, 'chartofaccounts', {
    account_name: zohoAccountName,
    account_code: clean(qb.AcctNum),
    account_type: mappedType,
    description: clean(qb.Description) || `Migrated from QuickBooks. QBO Account ID: ${qb.Id}`,
    parent_account_id: parentId,
    show_on_dashboard: mappedType === 'bank' || mappedType === 'cash' || mappedType === 'credit_card',
    custom_fields: customField(config.custom_field_ids?.account_qbo_id, qb.Id)
  });
}

function buildContact(config, maps, qb, entity) {
  const name = clean(qb.DisplayName || qb.FullyQualifiedName || qb.CompanyName);
  if (!name) {
    return quarantine(entity, qb, 'CONTACT_NAME_MISSING', 'QuickBooks contact has no usable display name.', 'DisplayName', '');
  }

  const key = sourceKey(entity, qb.Id);
  const existing = maps.existing_by_source_key?.[key];
  if (existing) {
    return { json: { outcome: 'skipped_existing', source_entity: entity, source_id: clean(qb.Id), target_id: clean(existing) } };
  }

  const parts = name.split(/\s+/).filter(Boolean);
  const firstName = clean(qb.GivenName) || parts[0] || (entity === 'Vendor' ? 'Vendor' : 'Customer');
  const lastName = clean(qb.FamilyName) || (parts.length > 1 ? parts.at(-1) : '.');
  const cfId = config.custom_field_ids?.contact_qbo_id;

  return ready(config, entity, qb, 'contacts', {
    contact_name: name,
    company_name: clean(qb.CompanyName) || name,
    contact_type: entity === 'Vendor' ? 'vendor' : 'customer',
    customer_sub_type: entity === 'Customer' ? (qb.CompanyName ? 'business' : 'individual') : undefined,
    vendor_sub_type: entity === 'Vendor' ? (qb.CompanyName ? 'business' : 'individual') : undefined,
    website: clean(qb.WebAddr?.URI),
    currency_code: clean(qb.CurrencyRef?.value),
    notes: clean(qb.Notes) || `Migrated from QuickBooks. ${key}`,
    billing_address: address(qb.BillAddr),
    shipping_address: address(qb.ShipAddr),
    contact_persons: [{
      first_name: firstName,
      last_name: lastName,
      email: clean(qb.PrimaryEmailAddr?.Address),
      phone: clean(qb.PrimaryPhone?.FreeFormNumber),
      mobile: clean(qb.Mobile?.FreeFormNumber),
      is_primary_contact: true
    }],
    custom_fields: customField(cfId, `${entity}:${qb.Id}`)
  });
}

function buildItem(config, maps, qb) {
  if (qb.Type === 'Category' || qb.Type === 'Group') {
    return quarantine('Item', qb, 'UNSUPPORTED_ITEM_TYPE',
      'QBO Category/Group requires an explicit Zoho item policy.', 'Type', qb.Type);
  }

  const incomeAccountId = resolveId(maps, 'account_by_qbo_id', qb.IncomeAccountRef);
  if (!incomeAccountId) {
    return quarantine('Item', qb, 'INCOME_ACCOUNT_UNMAPPED',
      'Item income account is not mapped.', 'IncomeAccountRef', qb.IncomeAccountRef?.value);
  }

  const purchaseAccountId = qb.ExpenseAccountRef
    ? resolveId(maps, 'account_by_qbo_id', qb.ExpenseAccountRef)
    : '';
  if (qb.ExpenseAccountRef && !purchaseAccountId) {
    return quarantine('Item', qb, 'PURCHASE_ACCOUNT_UNMAPPED',
      'Item purchase account is not mapped.', 'ExpenseAccountRef', qb.ExpenseAccountRef?.value);
  }

  const inventoryAccountId = qb.AssetAccountRef
    ? resolveId(maps, 'account_by_qbo_id', qb.AssetAccountRef)
    : '';
  if (qb.AssetAccountRef && !inventoryAccountId) {
    return quarantine('Item', qb, 'INVENTORY_ACCOUNT_UNMAPPED',
      'Item inventory asset account is not mapped.', 'AssetAccountRef', qb.AssetAccountRef?.value);
  }

  const cfId = config.custom_field_ids?.item_qbo_id;
  return ready(config, 'Item', qb, 'items', {
    name: clean(qb.Name),
    sku: clean(qb.Sku),
    rate: num(qb.UnitPrice),
    purchase_rate: qb.PurchaseCost === undefined ? undefined : num(qb.PurchaseCost),
    description: clean(qb.Description || qb.FullyQualifiedName),
    purchase_description: clean(qb.PurchaseDesc),
    product_type: qb.Type === 'Service' ? 'service' : 'goods',
    is_taxable: Boolean(qb.Taxable),
    account_id: incomeAccountId,
    purchase_account_id: purchaseAccountId,
    inventory_account_id: inventoryAccountId,
    custom_fields: customField(cfId, qb.Id)
  });
}

function salesLines(config, maps, qb, entity) {
  const result = [];
  for (const line of qb.Line || []) {
    if (line.DetailType === 'SubTotalLineDetail') continue;
    if (line.DetailType !== 'SalesItemLineDetail') {
      return { error: quarantine(entity, qb, 'UNSUPPORTED_SALES_LINE',
        'Document contains a discount/group/description line that needs an explicit rule; no partial document was created.',
        'Line.DetailType', line.DetailType, { source_line_id: clean(line.Id) }) };
    }

    const detail = line.SalesItemLineDetail || {};
    const itemId = resolveId(maps, 'item_by_qbo_id', detail.ItemRef);
    if (!itemId) {
      return { error: quarantine(entity, qb, 'ITEM_UNMAPPED',
        'A source line item is not mapped; the whole document is quarantined.',
        'ItemRef', detail.ItemRef?.value, { source_line_id: clean(line.Id) }) };
    }

    const qbTaxCode = clean(detail.TaxCodeRef?.value);
    const taxId = taxIdFor(config, detail.TaxCodeRef);
    if (num(qb.TxnTaxDetail?.TotalTax) !== 0 && qbTaxCode && !taxId) {
      return { error: quarantine(entity, qb, 'TAX_CODE_UNMAPPED',
        'Tax-bearing document has an unmapped tax code.', 'TaxCodeRef', qbTaxCode,
        { source_line_id: clean(line.Id) }) };
    }

    const quantity = detail.Qty === undefined ? 1 : num(detail.Qty);
    const sourceLineAmount = round(line.Amount, 2);
    const tolerance = num(config.amount_tolerance || 0.01);

    if (quantity === 0 && Math.abs(sourceLineAmount) > tolerance) {
      return { error: quarantine(entity, qb, 'INVALID_SALES_LINE_QUANTITY',
        'QBO sales line has a non-zero amount but zero quantity.', 'SalesItemLineDetail.Qty', detail.Qty,
        { source_line_id: clean(line.Id), source_line_amount: sourceLineAmount }) };
    }

    let rate = detail.UnitPrice === undefined
      ? (quantity === 0 ? 0 : sourceLineAmount / quantity)
      : num(detail.UnitPrice);
    const calculatedAmount = round(quantity * rate, 2);
    if (quantity !== 0 && Math.abs(calculatedAmount - sourceLineAmount) > tolerance) {
      rate = round(sourceLineAmount / quantity, 6);
    }

    result.push(compact({
      item_id: itemId,
      description: clean(line.Description),
      quantity,
      rate,
      tax_id: taxId,
      item_order: line.LineNum === undefined ? result.length + 1 : num(line.LineNum)
    }));
  }
  return { lines: result };
}

function buildInvoice(config, maps, qb) {
  const customerId = resolveId(maps, 'customer_by_qbo_id', qb.CustomerRef);
  if (!customerId) {
    return quarantine('Invoice', qb, 'CUSTOMER_UNMAPPED', 'Invoice customer is not mapped.', 'CustomerRef', qb.CustomerRef?.value);
  }

  const built = salesLines(config, maps, qb, 'Invoice');
  if (built.error) return built.error;
  if (!built.lines.length) {
    return quarantine('Invoice', qb, 'NO_POSTABLE_LINES', 'Invoice contains no supported sales lines.', 'Line', '');
  }

  const lineAmount = (qb.Line || [])
    .filter((line) => line.DetailType === 'SalesItemLineDetail')
    .reduce((sum, line) => sum + num(line.Amount), 0);
  const sourceTax = num(qb.TxnTaxDetail?.TotalTax);
  const difference = round(num(qb.TotalAmt) - lineAmount - sourceTax, 2);
  const tolerance = num(config.amount_tolerance || 0.01);
  if (Math.abs(difference) > tolerance) {
    return quarantine('Invoice', qb, 'INVOICE_TOTAL_UNEXPLAINED',
      'QBO total cannot be reproduced from supported lines and tax; likely discount/shipping/rounding data needs mapping.',
      'TotalAmt', qb.TotalAmt, { computed_before_adjustment: round(lineAmount + sourceTax, 2), difference });
  }

  let invoiceNum = clean(qb.DocNumber) || `QB-${qb.Id}`;
  if (clean(qb.Id) === '5450') invoiceNum = '32639-1';
  if (clean(qb.Id) === '5451') invoiceNum = '32640-1';

  const cfId = config.custom_field_ids?.invoice_qbo_id;
  return ready(config, 'Invoice', qb, 'invoices', {
    customer_id: customerId,
    invoice_number: invoiceNum,
    reference_number: sourceKey('Invoice', qb.Id),
    date: clean(qb.TxnDate),
    due_date: clean(qb.DueDate || qb.TxnDate),
    exchange_rate: qb.ExchangeRate === undefined ? undefined : num(qb.ExchangeRate),
    line_items: built.lines,
    adjustment: difference === 0 ? undefined : difference,
    adjustment_description: difference === 0 ? undefined : 'Verified QBO rounding difference',
    notes: clean(qb.CustomerMemo?.value || qb.PrivateNote) || 'Migrated from QuickBooks',
    custom_fields: customField(cfId, qb.Id)
  });
}

function buildCustomerPayment(config, maps, qb) {
  const key = sourceKey('Payment', qb.Id);
  const existing = maps.existing_by_source_key?.[key];
  if (existing) {
    return {
      json: {
        outcome: 'skipped_existing',
        source_entity: 'Payment',
        source_id: clean(qb.Id),
        source_key: key,
        target_id: clean(existing)
      }
    };
  }

  if (num(qb.TotalAmt) === 0) {
    return { json: { outcome: 'skipped_existing', source_entity: 'Payment', source_id: clean(qb.Id), note: 'Ignored zero-dollar QBO dummy payment' } };
  }

  const customerId = resolveId(maps, 'customer_by_qbo_id', qb.CustomerRef);
  if (!customerId) {
    return quarantine('Payment', qb, 'CUSTOMER_UNMAPPED', 'Payment customer is not mapped.', 'CustomerRef', qb.CustomerRef?.value);
  }

  const invoices = [];
  for (const line of qb.Line || []) {
    for (const linked of line.LinkedTxn || []) {
      if (linked.TxnType !== 'Invoice') {
        return quarantine('Payment', qb, 'UNSUPPORTED_PAYMENT_LINK',
          'Payment links to a non-invoice transaction and needs an explicit credit/refund rule.', 'LinkedTxn.TxnType', linked.TxnType);
      }
      const invoiceId = resolveId(maps, 'invoice_by_qbo_id', linked.TxnId);
      if (!invoiceId) {
        return quarantine('Payment', qb, 'INVOICE_UNMAPPED',
          'A payment allocation points to an invoice that is not mapped; the whole payment is quarantined.',
          'LinkedTxn.TxnId', linked.TxnId);
      }

      const amountApplied = round(line.Amount, 2);
      if (amountApplied <= 0) {
        return quarantine('Payment', qb, 'INVALID_INVOICE_ALLOCATION_AMOUNT',
          'Zoho requires every linked invoice allocation to have a positive amount.',
          'Line.Amount', line.Amount, { linked_invoice_qbo_id: clean(linked.TxnId) });
      }

      invoices.push({ invoice_id: invoiceId, amount_applied: amountApplied });
    }
  }

  const applied = round(invoices.reduce((sum, line) => sum + num(line.amount_applied), 0), 2);
  const unapplied = round(qb.UnappliedAmt, 2);
  const total = round(qb.TotalAmt, 2);
  const tolerance = num(config.amount_tolerance || 0.01);

  if (total <= 0) {
    return quarantine('Payment', qb, 'ZERO_PAYMENT_NOT_POSTABLE',
      'QuickBooks payment total is zero or negative; do not create it as a Zoho customer payment.',
      'TotalAmt', qb.TotalAmt, { applied, unapplied, total });
  }

  if (invoices.length === 0) {
    return quarantine('Payment', qb, 'NO_INVOICE_ALLOCATIONS',
      'QuickBooks payment has no linked invoice. It must not be posted through the invoice-payment endpoint.',
      'Line.LinkedTxn', '', { applied, unapplied, total });
  }

  if (Math.abs(applied + unapplied - total) > tolerance) {
    return quarantine('Payment', qb, 'PAYMENT_TOTAL_MISMATCH',
      'Applied plus unapplied amount does not equal QBO payment total.', 'TotalAmt', qb.TotalAmt,
      { applied, unapplied, total });
  }

  const accountId = resolveId(maps, 'account_by_qbo_id', qb.DepositToAccountRef);
  if (qb.DepositToAccountRef && !accountId) {
    return quarantine('Payment', qb, 'DEPOSIT_ACCOUNT_UNMAPPED',
      'Payment deposit account is not mapped.', 'DepositToAccountRef', qb.DepositToAccountRef?.value);
  }

  return ready(config, 'Payment', qb, 'customerpayments', {
    customer_id: customerId,
    payment_mode: paymentMode(qb),
    amount: total,
    date: clean(qb.TxnDate),
    reference_number: key,
    description: clean(qb.PrivateNote) || `Migrated from QuickBooks Payment ${qb.Id}`,
    invoices,
    exchange_rate: qb.ExchangeRate === undefined ? 1 : num(qb.ExchangeRate),
    account_id: accountId
  });
}

function purchaseLines(config, maps, qb, entity) {
  const output = [];
  for (const line of qb.Line || []) {
    const lineAmount = round(line.Amount, 2);
    if (lineAmount === 0) continue;

    if (line.DetailType === 'AccountBasedExpenseLineDetail') {
      const detail = line.AccountBasedExpenseLineDetail || {};
      const accountId = resolveId(maps, 'account_by_qbo_id', detail.AccountRef);
      if (!accountId) {
        return { error: quarantine(entity, qb, 'EXPENSE_ACCOUNT_UNMAPPED',
          'Expense line account is not mapped; the whole document is quarantined.',
          'AccountRef', detail.AccountRef?.value, { source_line_id: clean(line.Id) }) };
      }
      const taxId = taxIdFor(config, detail.TaxCodeRef);
      if (num(qb.TxnTaxDetail?.TotalTax) !== 0 && detail.TaxCodeRef && !taxId) {
        return { error: quarantine(entity, qb, 'TAX_CODE_UNMAPPED',
          'Tax-bearing expense line has an unmapped tax code.', 'TaxCodeRef', detail.TaxCodeRef?.value) };
      }
      output.push(compact({
        account_id: accountId,
        description: clean(line.Description),
        rate: lineAmount,
        quantity: 1,
        tax_id: taxId,
        item_order: output.length + 1
      }));
      continue;
    }

    if (line.DetailType === 'ItemBasedExpenseLineDetail') {
      const detail = line.ItemBasedExpenseLineDetail || {};
      const itemId = resolveId(maps, 'item_by_qbo_id', detail.ItemRef);
      if (!itemId) {
        return { error: quarantine(entity, qb, 'ITEM_UNMAPPED',
          'Purchase line item is not mapped; the whole document is quarantined.',
          'ItemRef', detail.ItemRef?.value, { source_line_id: clean(line.Id) }) };
      }
      const taxId = taxIdFor(config, detail.TaxCodeRef);
      if (num(qb.TxnTaxDetail?.TotalTax) !== 0 && detail.TaxCodeRef && !taxId) {
        return { error: quarantine(entity, qb, 'TAX_CODE_UNMAPPED',
          'Tax-bearing purchase line has an unmapped tax code.', 'TaxCodeRef', detail.TaxCodeRef?.value) };
      }
      const qty = detail.Qty === undefined ? 1 : num(detail.Qty);
      const rate = detail.UnitPrice === undefined ? (qty === 0 ? lineAmount : round(lineAmount / qty, 2)) : num(detail.UnitPrice);
      output.push(compact({
        item_id: itemId,
        description: clean(line.Description),
        rate: rate,
        quantity: qty,
        tax_id: taxId,
        item_order: output.length + 1
      }));
      continue;
    }

    return { error: quarantine(entity, qb, 'UNSUPPORTED_PURCHASE_LINE',
      'Purchase document contains an unsupported line type; no partial document was created.',
      'Line.DetailType', line.DetailType, { source_line_id: clean(line.Id) }) };
  }
  return { lines: output };
}

function buildBill(config, maps, qb) {
  const vendorId = resolveId(maps, 'vendor_by_qbo_id', qb.VendorRef);
  if (!vendorId) {
    return quarantine('Bill', qb, 'VENDOR_UNMAPPED', 'Bill vendor is not mapped.', 'VendorRef', qb.VendorRef?.value);
  }
  const built = purchaseLines(config, maps, qb, 'Bill');
  if (built.error) return built.error;
  if (!built.lines.length) return quarantine('Bill', qb, 'NO_POSTABLE_LINES', 'Bill has no supported lines.', 'Line', '');

  const cfId = config.custom_field_ids?.bill_qbo_id;
  return ready(config, 'Bill', qb, 'bills', {
    vendor_id: vendorId,
    bill_number: clean(qb.DocNumber) || `QB-${qb.Id}`,
    reference_number: sourceKey('Bill', qb.Id),
    date: clean(qb.TxnDate),
    due_date: clean(qb.DueDate || qb.TxnDate),
    exchange_rate: qb.ExchangeRate === undefined ? undefined : num(qb.ExchangeRate),
    line_items: built.lines,
    notes: clean(qb.PrivateNote) || 'Migrated from QuickBooks',
    custom_fields: customField(cfId, qb.Id)
  });
}

function buildVendorPayment(config, maps, qb) {
  const initialTotal = round(qb.TotalAmt, 2);
  const initialLines = Array.isArray(qb.Line) ? qb.Line : [];
  if (Math.abs(initialTotal) <= num(config.amount_tolerance || 0.01) && initialLines.length === 0) {
    return { json: {
      outcome: 'skipped_zero_value',
      source_entity: 'BillPayment',
      source_id: clean(qb.Id),
      source_doc_number: clean(qb.DocNumber),
      source_key: sourceKey('BillPayment', qb.Id),
      skip_reason: 'Zero-value transaction with no allocations; no accounting impact.'
    }};
  }
  const vendorId = resolveId(maps, 'vendor_by_qbo_id', qb.VendorRef);
  if (!vendorId) {
    return quarantine('BillPayment', qb, 'VENDOR_UNMAPPED', 'Bill payment vendor is not mapped.', 'VendorRef', qb.VendorRef?.value);
  }

  const bills = [];
  for (const line of qb.Line || []) {
    for (const linked of line.LinkedTxn || []) {
      if (linked.TxnType !== 'Bill') {
        return quarantine('BillPayment', qb, 'UNSUPPORTED_BILL_PAYMENT_LINK',
          'Bill payment links to a non-bill transaction and needs a credit rule.', 'LinkedTxn.TxnType', linked.TxnType);
      }
      const billId = resolveId(maps, 'bill_by_qbo_id', linked.TxnId);
      if (!billId) {
        return quarantine('BillPayment', qb, 'BILL_UNMAPPED',
          'A bill payment allocation points to a bill that is not mapped.', 'LinkedTxn.TxnId', linked.TxnId);
      }
      bills.push({ bill_id: billId, amount_applied: num(line.Amount) });
    }
  }

  if (!bills.length) {
  if (config.allow_unapplied_vendor_payments !== true) {
    return quarantine(
      'BillPayment',
      qb,
      'NO_BILL_ALLOCATIONS',
      'Unapplied vendor payment requires allow_unapplied_vendor_payments=true.',
      'Line',
      ''
    );
  }

  const paymentAccountRef =
    qb.CheckPayment?.BankAccountRef ||
    qb.CreditCardPayment?.CCAccountRef;

  const paidThroughId = resolveId(
    maps,
    'account_by_qbo_id',
    paymentAccountRef
  );

  if (!paidThroughId) {
    return quarantine(
      'BillPayment',
      qb,
      'PAID_THROUGH_ACCOUNT_UNMAPPED',
      'Vendor advance bank/credit-card account is not mapped.',
      'PaymentAccountRef',
      paymentAccountRef?.value
    );
  }

  const total = round(qb.TotalAmt, 2);

  if (total <= 0) {
    return quarantine(
      'BillPayment',
      qb,
      'INVALID_VENDOR_ADVANCE_AMOUNT',
      'Vendor advance amount must be greater than zero.',
      'TotalAmt',
      qb.TotalAmt
    );
  }

  return ready(config, 'BillPayment', qb, 'vendorpayments', {
    vendor_id: vendorId,
    date: clean(qb.TxnDate),
    exchange_rate:
      qb.ExchangeRate === undefined ? 1 : num(qb.ExchangeRate),
    amount: total,
    paid_through_account_id: paidThroughId,
    payment_mode: paymentMode(qb),
    description:
      clean(qb.PrivateNote) ||
      `Migrated unapplied QuickBooks BillPayment ${qb.Id}`,
    reference_number: sourceKey('BillPayment', qb.Id)
  });
}

  const paymentAccountRef = qb.CheckPayment?.BankAccountRef || qb.CreditCardPayment?.CCAccountRef;
  const paidThroughId = resolveId(maps, 'account_by_qbo_id', paymentAccountRef);
  if (!paidThroughId) {
    return quarantine('BillPayment', qb, 'PAID_THROUGH_ACCOUNT_UNMAPPED',
      'Vendor payment bank/credit-card account is not mapped.', 'PaymentAccountRef', paymentAccountRef?.value);
  }

  const applied = round(bills.reduce((sum, line) => sum + num(line.amount_applied), 0), 2);
  const total = round(qb.TotalAmt, 2);
  if (Math.abs(applied - total) > num(config.amount_tolerance || 0.01)) {
    return quarantine('BillPayment', qb, 'VENDOR_PAYMENT_TOTAL_MISMATCH',
      'Applied bill amounts do not equal the QBO bill payment total.', 'TotalAmt', qb.TotalAmt, { applied, total });
  }

  return ready(config, 'BillPayment', qb, 'vendorpayments', {
    vendor_id: vendorId,
    bills,
    date: clean(qb.TxnDate),
    exchange_rate: qb.ExchangeRate === undefined ? 1 : num(qb.ExchangeRate),
    amount: total,
    paid_through_account_id: paidThroughId,
    payment_mode: paymentMode(qb),
    description: clean(qb.PrivateNote) || `Migrated from QuickBooks BillPayment ${qb.Id}`,
    reference_number: sourceKey('BillPayment', qb.Id)
  });
}

function buildExpense(config, maps, qb) {
  const tolerance = num(config.amount_tolerance || 0.01);
  const initialLines = Array.isArray(qb.Line) ? qb.Line : [];
  const initialTotal = round(qb.TotalAmt, 2);
  const hasNonZeroLine = initialLines.some(
    line => Math.abs(round(line.Amount, 2)) > tolerance
  );
  if (Math.abs(initialTotal) <= tolerance && !hasNonZeroLine) {
    return { json: {
      outcome: 'skipped_zero_value',
      source_entity: 'Purchase',
      source_id: clean(qb.Id),
      source_doc_number: clean(qb.DocNumber),
      source_key: sourceKey('Purchase', qb.Id),
      skip_reason: 'Zero-value purchase with no non-zero accounting lines.'
    }};
  }
  const sourceQboAccountId = clean(qb.AccountRef?.value);
  const paidThroughId = resolveId(maps, 'account_by_qbo_id', qb.AccountRef);

  if (!paidThroughId) {
    return quarantine('Purchase', qb, 'PAID_THROUGH_ACCOUNT_UNMAPPED',
      'Purchase bank/credit-card account is not mapped.', 'AccountRef', sourceQboAccountId);
  }

  const sourceMeta = maps.account_meta_by_qbo_id?.[sourceQboAccountId] || {};
  const sourceAccountType = clean(sourceMeta.zoho_account_type).toLowerCase();
  const bankLikeTypes = new Set(['bank', 'cash', 'payment_clearing_account']);
  const fundingAccountTypes = new Set([...bankLikeTypes, 'credit_card']);
  const purchaseBalanceSheetTypes = new Set([
    'other_current_asset', 'fixed_asset', 'other_asset', 'stock',
    'non_current_asset', 'intangible_asset', 'deferred_tax_asset',
    'capital_work_in_progress', 'intangible_assets_under_development',
    'other_current_liability', 'long_term_liability',
    'non_current_liability', 'other_liability', 'deferred_tax_liability',
    'equity'
  ]);

  const nonZeroLines = (qb.Line || []).filter((line) => Math.abs(round(line.Amount, 2)) > tolerance);

  // QBO exposes both ordinary credit-card charges and Credit Card Credits as
  // Purchase entities. The structural discriminator is Purchase.Credit=true.
  // Do not use memo/description keywords and do not infer a refund merely from
  // PaymentType=CreditCard, because that would misclassify normal card expenses.
  const qboCreditFlag = qb.Credit === true || clean(qb.Credit).toLowerCase() === 'true';
  const qboPaymentType = clean(qb.PaymentType).toLowerCase();
  const isCreditCardCredit =
    qboCreditFlag &&
    qboPaymentType === 'creditcard' &&
    sourceAccountType === 'credit_card';

  if (isCreditCardCredit) {
    if (nonZeroLines.length !== 1) {
      return quarantine('Purchase', qb, 'COMPLEX_CREDIT_CARD_REFUND',
        'Credit-card refund has multiple non-zero category lines. Review manually instead of collapsing accounting lines.',
        'Line', nonZeroLines.map((line) => clean(line.Id)).join(','),
        { qbo_credit: true, qbo_payment_type: clean(qb.PaymentType) });
    }

    const refundLine = nonZeroLines[0];
    if (refundLine.DetailType !== 'AccountBasedExpenseLineDetail') {
      return quarantine('Purchase', qb, 'UNSUPPORTED_CREDIT_CARD_REFUND_LINE',
        'Credit-card refund must contain one account-based expense line.',
        'Line.DetailType', refundLine.DetailType,
        { source_line_id: clean(refundLine.Id) });
    }

    const refundAccountRef = refundLine.AccountBasedExpenseLineDetail?.AccountRef;
    const refundAccountQboId = clean(refundAccountRef?.value);
    const refundAccountMeta = maps.account_meta_by_qbo_id?.[refundAccountQboId] || {};
    const refundAccountType = clean(refundAccountMeta.zoho_account_type).toLowerCase();
    const allowedRefundSourceTypes = new Set(['expense', 'other_expense', 'cost_of_goods_sold']);
    if (!allowedRefundSourceTypes.has(refundAccountType)) {
      return quarantine('Purchase', qb, 'CREDIT_CARD_REFUND_SOURCE_NOT_EXPENSE',
        'Credit-card credit category must be an expense/COGS account; bank-funded card payments belong to credit_card_repayments.',
        'Line.AccountRef', refundAccountQboId,
        { source_line_id: clean(refundLine.Id), qbo_account_type: refundAccountType });
    }

    const refundFromAccountId = resolveId(maps, 'account_by_qbo_id', refundAccountRef);
    if (!refundFromAccountId) {
      return quarantine('Purchase', qb, 'CREDIT_CARD_REFUND_ACCOUNT_UNMAPPED',
        'Credit-card refund expense account is not mapped.',
        'Line.AccountRef', refundAccountQboId,
        { source_line_id: clean(refundLine.Id) });
    }

    const lineAmount = Math.abs(round(refundLine.Amount, 2));
    const total = Math.abs(round(qb.TotalAmt, 2));
    if (total <= 0 || lineAmount <= 0 || Math.abs(lineAmount - total) > tolerance) {
      return quarantine('Purchase', qb, 'CREDIT_CARD_REFUND_TOTAL_MISMATCH',
        'Credit-card refund line amount does not match QuickBooks TotalAmt.',
        'TotalAmt', qb.TotalAmt,
        { source_line_amount: lineAmount, difference: round(total - lineAmount, 2) });
    }

    const result = ready(config, 'Purchase', qb, 'banktransactions', {
      from_account_id: refundFromAccountId,
      to_account_id: paidThroughId,
      transaction_type: 'refund',
      amount: total,
      date: clean(qb.TxnDate),
      payment_mode: 'others',
      reference_number: sourceKey('Purchase', qb.Id),
      description: clean(qb.PrivateNote) || clean(refundLine.Description) ||
        ('QuickBooks credit-card refund ' + clean(qb.Id))
    });
    result.json.migration_kind = 'credit_card_refund';
    result.json.qbo_credit = true;
    result.json.qbo_payment_type = clean(qb.PaymentType);
    return result;
  }

  const cardTargetLines = nonZeroLines.filter((line) => {
    if (line.DetailType !== 'AccountBasedExpenseLineDetail') return false;
    const ref = line.AccountBasedExpenseLineDetail?.AccountRef;
    const meta = maps.account_meta_by_qbo_id?.[clean(ref?.value)] || {};
    return clean(meta.zoho_account_type).toLowerCase() === 'credit_card';
  });

  // In historical QBO files, a Pay-down-credit-card transaction can be exposed
  // as a bank-paid Purchase whose sole account line is the credit-card liability.
  if (bankLikeTypes.has(sourceAccountType) && cardTargetLines.length) {
    if (nonZeroLines.length !== 1 || cardTargetLines.length !== 1) {
      return quarantine('Purchase', qb, 'COMPLEX_CREDIT_CARD_REPAYMENT',
        'Credit-card repayment contains multiple non-zero lines and must be reviewed before posting.',
        'Line', cardTargetLines.map((line) => clean(line.Id)).join(','));
    }

    const cardLine = cardTargetLines[0];
    const cardRef = cardLine.AccountBasedExpenseLineDetail?.AccountRef;
    const creditCardId = resolveId(maps, 'account_by_qbo_id', cardRef);
    const lineAmount = Math.abs(round(cardLine.Amount, 2));
    const total = Math.abs(round(qb.TotalAmt, 2));

    if (!creditCardId) {
      return quarantine('Purchase', qb, 'CREDIT_CARD_ACCOUNT_UNMAPPED',
        'Credit-card repayment destination account is not mapped.', 'Line.AccountRef', cardRef?.value,
        { source_line_id: clean(cardLine.Id) });
    }
    if (paidThroughId === creditCardId) {
      return quarantine('Purchase', qb, 'SAME_ACCOUNT_CARD_REPAYMENT',
        'Credit-card repayment source and destination resolve to the same Zoho account.',
        'AccountRef/Line.AccountRef', sourceQboAccountId,
        { source_line_id: clean(cardLine.Id) });
    }
    if (total <= 0 || Math.abs(lineAmount - total) > tolerance) {
      return quarantine('Purchase', qb, 'CARD_REPAYMENT_TOTAL_MISMATCH',
        'Credit-card repayment line amount does not match QuickBooks TotalAmt.', 'TotalAmt', qb.TotalAmt,
        { source_line_amount: lineAmount, difference: round(total - lineAmount, 2) });
    }

    const result = ready(config, 'Purchase', qb, 'banktransactions', {
      from_account_id: paidThroughId,
      to_account_id: creditCardId,
      transaction_type: 'card_payment',
      amount: total,
      date: clean(qb.TxnDate),
      reference_number: sourceKey('Purchase', qb.Id),
      description: clean(qb.PrivateNote) ||
        ('QuickBooks credit-card repayment ' + clean(qb.Id))
    });
    result.json.migration_kind = 'credit_card_repayment';
    result.json.qbo_payment_type = clean(qb.PaymentType);
    return result;
  }

  // QBO checks written from a bank account to a loan/asset/equity account are
  // balance-sheet transfers, even though the QBO API exposes them as Purchase.
  const balanceSheetTargetLines = nonZeroLines.filter((line) => {
    if (line.DetailType !== 'AccountBasedExpenseLineDetail') return false;
    const ref = line.AccountBasedExpenseLineDetail?.AccountRef;
    const meta = maps.account_meta_by_qbo_id?.[clean(ref?.value)] || {};
    return purchaseBalanceSheetTypes.has(clean(meta.zoho_account_type).toLowerCase());
  });

  if (fundingAccountTypes.has(sourceAccountType) && balanceSheetTargetLines.length) {
    if (balanceSheetTargetLines.length !== nonZeroLines.length) {
      return quarantine('Purchase', qb, 'MIXED_LOAN_TRANSFER_LINES',
        'Bank check contains both balance-sheet and expense lines; manual review is required.',
        'Line', nonZeroLines.map((line) => clean(line.Id)).join(','));
    }

    const total = Math.abs(round(qb.TotalAmt, 2));
    const destinationTotal = round(balanceSheetTargetLines.reduce(
      (sum, line) => sum + Math.abs(round(line.Amount, 2)), 0), 2);
    if (total <= 0 || Math.abs(destinationTotal - total) > tolerance) {
      return quarantine('Purchase', qb, 'LOAN_TRANSFER_TOTAL_MISMATCH',
        'Balance-sheet transfer lines do not match QuickBooks TotalAmt.', 'TotalAmt', qb.TotalAmt,
        { destination_total: destinationTotal, difference: round(total - destinationTotal, 2) });
    }

    const journalLines = [];
    for (const line of balanceSheetTargetLines) {
      const ref = line.AccountBasedExpenseLineDetail?.AccountRef;
      const destinationId = resolveId(maps, 'account_by_qbo_id', ref);
      if (!destinationId) {
        return quarantine('Purchase', qb, 'LOAN_ACCOUNT_UNMAPPED',
          'Loan/balance-sheet destination account is not mapped.', 'Line.AccountRef', ref?.value,
          { source_line_id: clean(line.Id) });
      }
      if (destinationId === paidThroughId) {
        return quarantine('Purchase', qb, 'SAME_ACCOUNT_LOAN_TRANSFER',
          'Loan transfer source and destination resolve to the same Zoho account.',
          'AccountRef/Line.AccountRef', sourceQboAccountId,
          { source_line_id: clean(line.Id) });
      }
      journalLines.push({
        account_id: destinationId,
        debit_or_credit: 'debit',
        amount: Math.abs(round(line.Amount, 2)),
        description: clean(line.Description) || clean(ref?.name) || 'Loan transfer destination'
      });
    }
    journalLines.push({
      account_id: paidThroughId,
      debit_or_credit: 'credit',
      amount: total,
      description: clean(qb.AccountRef?.name) || 'Bank transfer source'
    });

    const result = ready(config, 'Purchase', qb, 'journals', {
      journal_date: clean(qb.TxnDate),
      reference_number: sourceKey('Purchase', qb.Id),
      notes: clean(qb.PrivateNote) || ('QuickBooks bank check to loan/balance-sheet account ' + clean(qb.Id)),
      status: 'published',
      line_items: journalLines
    });
    result.json.migration_kind = 'loan_check_balance_sheet_transfer_journal';
    result.json.qbo_payment_type = clean(qb.PaymentType);
    return result;
  }

  const expenseLines = [];
  for (const line of qb.Line || []) {
    const lineAmount = round(line.Amount, 2);
    if (lineAmount === 0) continue;
    if (lineAmount < 0) {
      const approvedIds = new Set(config.approved_negative_expense_netting_source_ids || []);
      if (!approvedIds.has(clean(qb.Id))) {
        return quarantine('Purchase', qb, 'NEGATIVE_EXPENSE_LINE',
          'Negative purchase line requires reviewed netting approval.', 'Line.Amount', line.Amount,
          { source_line_id: clean(line.Id) });
      }
    }

    let detail;
    let accountId = '';
    if (line.DetailType === 'AccountBasedExpenseLineDetail') {
      detail = line.AccountBasedExpenseLineDetail || {};
      accountId = resolveId(maps, 'account_by_qbo_id', detail.AccountRef);
      if (!accountId) {
        return quarantine('Purchase', qb, 'EXPENSE_ACCOUNT_UNMAPPED',
          'Expense line account is not mapped.', 'AccountRef', detail.AccountRef?.value,
          { source_line_id: clean(line.Id) });
      }
    } else if (line.DetailType === 'ItemBasedExpenseLineDetail') {
      detail = line.ItemBasedExpenseLineDetail || {};
      accountId = resolveId(maps, 'account_by_qbo_id', detail.ItemAccountRef) ||
        clean(config.approved_expense_item_account_overrides?.[clean(detail.ItemRef?.value)]);
      if (!accountId) {
        return quarantine('Purchase', qb, 'ITEM_EXPENSE_ACCOUNT_UNMAPPED',
          'Item-based expense needs its Zoho expense account mapping.', 'ItemRef', detail.ItemRef?.value,
          { source_line_id: clean(line.Id) });
      }
    } else {
      return quarantine('Purchase', qb, 'UNSUPPORTED_PURCHASE_LINE',
        'Expense contains an unsupported QBO line type.', 'Line.DetailType', line.DetailType,
        { source_line_id: clean(line.Id) });
    }

    const taxId = taxIdFor(config, detail.TaxCodeRef);
    if (num(qb.TxnTaxDetail?.TotalTax) !== 0 && detail.TaxCodeRef && !taxId) {
      return quarantine('Purchase', qb, 'TAX_CODE_UNMAPPED',
        'Tax-bearing expense line has an unmapped tax code.', 'TaxCodeRef', detail.TaxCodeRef?.value,
        { source_line_id: clean(line.Id) });
    }
    expenseLines.push(compact({
      account_id: accountId,
      description: clean(line.Description).slice(0, 100),
      amount: lineAmount,
      tax_id: taxId,
      item_order: expenseLines.length + 1
    }));
  }

  const groupedExpenseLines = new Map();
  for (const line of expenseLines) {
    const key = [clean(line.account_id), clean(line.tax_id)].join('|');
    const existing = groupedExpenseLines.get(key) || { ...line, amount: 0, description_parts: [] };
    existing.amount = round(existing.amount + num(line.amount), 2);
    if (clean(line.description)) existing.description_parts.push(clean(line.description));
    groupedExpenseLines.set(key, existing);
  }
  const netExpenseLines = [...groupedExpenseLines.values()]
    .map((line, index) => compact({
      account_id: line.account_id,
      amount: round(line.amount, 2),
      tax_id: line.tax_id,
      item_order: index + 1,
      description: line.description_parts.join(' | ').slice(0, 100)
    }))
    .filter(line => Math.abs(num(line.amount)) > tolerance);
  if (netExpenseLines.some(line => num(line.amount) <= 0)) {
    return quarantine('Purchase', qb, 'NON_POSITIVE_NET_EXPENSE_LINE',
      'Approved netting produced a zero or negative account total.', 'Line.Amount', '');
  }
  if (!netExpenseLines.length) {
    return quarantine('Purchase', qb, 'NO_POSTABLE_LINES',
      'Expense has no supported non-zero lines.', 'Line', '');
  }
  const total = round(qb.TotalAmt, 2);
  if (total <= 0) {
    return quarantine('Purchase', qb, 'INVALID_EXPENSE_TOTAL',
      'A normal Zoho expense must have a positive total.', 'TotalAmt', qb.TotalAmt);
  }

  const entityType = clean(qb.EntityRef?.type).toLowerCase();
  let vendorId;
  let customerId;
  if (entityType === 'vendor') {
    vendorId = resolveId(maps, 'vendor_by_qbo_id', qb.EntityRef);
    if (!vendorId) return quarantine('Purchase', qb, 'VENDOR_UNMAPPED',
      'Expense vendor is not mapped.', 'EntityRef', qb.EntityRef?.value);
  } else if (entityType === 'customer') {
    customerId = resolveId(maps, 'customer_by_qbo_id', qb.EntityRef);
    if (!customerId) return quarantine('Purchase', qb, 'CUSTOMER_UNMAPPED',
      'Expense customer is not mapped.', 'EntityRef', qb.EntityRef?.value);
  } else if (qb.EntityRef) {
    return quarantine('Purchase', qb, 'UNSUPPORTED_EXPENSE_PAYEE',
      'Employee or Other payee requires a separate Zoho mapping.', 'EntityRef.type', qb.EntityRef?.type);
  }

  return ready(config, 'Purchase', qb, 'expenses', {
    account_id: netExpenseLines[0].account_id,
    paid_through_account_id: paidThroughId,
    date: clean(qb.TxnDate),
    amount: total,
    line_items: netExpenseLines,
    reference_number: sourceKey('Purchase', qb.Id),
    description: clean(qb.PrivateNote).slice(0, 500) || 'Migrated from QuickBooks',
    vendor_id: vendorId,
    customer_id: customerId,
    exchange_rate: qb.ExchangeRate === undefined ? undefined : num(qb.ExchangeRate),
    is_inclusive_tax: qb.GlobalTaxCalculation === 'TaxInclusive'
  });
}

function buildTransfer(config, maps, qb) {
  const fromQboId = clean(qb.FromAccountRef?.value);
  const toQboId = clean(qb.ToAccountRef?.value);
  const fromId = resolveId(maps, 'account_by_qbo_id', qb.FromAccountRef);
  const toId = resolveId(maps, 'account_by_qbo_id', qb.ToAccountRef);

  if (!fromId || !toId) {
    return quarantine('Transfer', qb, 'TRANSFER_ACCOUNT_UNMAPPED',
      'Transfer source or destination account is not mapped.',
      !fromId ? 'FromAccountRef' : 'ToAccountRef',
      !fromId ? fromQboId : toQboId);
  }

  if (fromId === toId) {
    return quarantine('Transfer', qb, 'SAME_ACCOUNT_TRANSFER',
      'QuickBooks transfer source and destination resolve to the same Zoho account.',
      'FromAccountRef/ToAccountRef', fromQboId);
  }

  const fromMeta = maps.account_meta_by_qbo_id?.[fromQboId] || {};
  const toMeta = maps.account_meta_by_qbo_id?.[toQboId] || {};
  const fromType = clean(fromMeta.zoho_account_type).toLowerCase();
  const toType = clean(toMeta.zoho_account_type).toLowerCase();
  const bankLike = new Set(['bank', 'cash', 'payment_clearing_account']);
  const bankOrCard = new Set([...bankLike, 'credit_card']);
  const journalBalanceSheetTypes = new Set([
    ...bankOrCard,
    'other_current_asset', 'fixed_asset', 'other_asset', 'stock',
    'non_current_asset', 'intangible_asset', 'deferred_tax_asset',
    'capital_work_in_progress', 'intangible_assets_under_development',
    'other_current_liability', 'long_term_liability',
    'non_current_liability', 'other_liability', 'deferred_tax_liability',
    'equity'
  ]);

  const total = Math.abs(round(qb.Amount, 2));
  if (total <= 0) {
    return quarantine('Transfer', qb, 'INVALID_TRANSFER_AMOUNT',
      'Transfer amount must be positive.', 'Amount', qb.Amount);
  }

  // Zoho supports a direct card_payment for a bank/cash -> credit-card pair.
  if (bankLike.has(fromType) && toType === 'credit_card') {
    const result = ready(config, 'Transfer', qb, 'banktransactions', {
      from_account_id: fromId,
      to_account_id: toId,
      transaction_type: 'card_payment',
      amount: total,
      date: clean(qb.TxnDate),
      reference_number: sourceKey('Transfer', qb.Id),
      description: clean(qb.PrivateNote) || 'Migrated QuickBooks credit-card repayment'
    });
    result.json.migration_kind = 'credit_card_repayment';
    return result;
  }

  // Normal transfers between bank / cash / credit-card accounts can use the
  // Zoho banktransactions endpoint directly.
  if (bankOrCard.has(fromType) && bankOrCard.has(toType)) {
    return ready(config, 'Transfer', qb, 'banktransactions', {
      from_account_id: fromId,
      to_account_id: toId,
      transaction_type: 'transfer_fund',
      amount: total,
      date: clean(qb.TxnDate),
      reference_number: sourceKey('Transfer', qb.Id),
      description: clean(qb.PrivateNote) || 'Migrated from QuickBooks'
    });
  }

  // Zoho banktransactions rejects bank -> loan/liability combinations. Preserve
  // the exact QBO double entry through a manual journal instead:
  // destination account DEBIT, source account CREDIT.
  const oneSideIsBankOrCard = bankOrCard.has(fromType) || bankOrCard.has(toType);
  const journalPairIsSafe = journalBalanceSheetTypes.has(fromType) &&
    journalBalanceSheetTypes.has(toType) && oneSideIsBankOrCard;

  if (!journalPairIsSafe) {
    return quarantine('Transfer', qb, 'UNSUPPORTED_TRANSFER_ACCOUNT_PAIR',
      'Transfer account pair cannot be posted safely as a Zoho bank transaction or balance-sheet journal.',
      'FromAccountRef/ToAccountRef',
      fromQboId + ':' + fromType + ' -> ' + toQboId + ':' + toType,
      { from_zoho_account_id: fromId, to_zoho_account_id: toId });
  }

  let journalDate = clean(qb.TxnDate);
  const offsetDays = Number(config.loan_transfer_date_offset_days || 0);
  if (journalDate && Number.isInteger(offsetDays) && offsetDays !== 0) {
    const parsed = new Date(journalDate + 'T00:00:00.000Z');
    if (!Number.isNaN(parsed.getTime())) {
      parsed.setUTCDate(parsed.getUTCDate() + offsetDays);
      journalDate = parsed.toISOString().slice(0, 10);
    }
  }

  const result = ready(config, 'Transfer', qb, 'journals', {
    journal_date: journalDate,
    reference_number: sourceKey('Transfer', qb.Id),
    status: 'published',
    notes: clean(qb.PrivateNote) ||
      ('Migrated QuickBooks Transfer ' + clean(qb.Id)),
    line_items: [
      {
        account_id: toId,
        debit_or_credit: 'debit',
        amount: total,
        description: clean(qb.ToAccountRef?.name) || 'Transfer destination'
      },
      {
        account_id: fromId,
        debit_or_credit: 'credit',
        amount: total,
        description: clean(qb.FromAccountRef?.name) || 'Transfer source'
      }
    ]
  });
  result.json.migration_kind = 'loan_balance_sheet_transfer_journal';
  result.json.qbo_from_account_type = fromType;
  result.json.qbo_to_account_type = toType;
  return result;
}

function buildDeposit(config, maps, qb) {
  const key = sourceKey('Deposit', qb.Id);

  const existing = maps.existing_by_source_key?.[key];
  if (existing) {
    return {
      json: {
        outcome: 'skipped_existing',
        source_entity: 'Deposit',
        source_id: clean(qb.Id),
        source_key: key,
        target_id: clean(existing)
      }
    };
  }

  const toId = resolveId(
    maps,
    'account_by_qbo_id',
    qb.DepositToAccountRef
  );

  if (!toId) {
    return quarantine(
      'Deposit',
      qb,
      'DEPOSIT_DESTINATION_UNMAPPED',
      'QuickBooks deposit destination account is not mapped.',
      'DepositToAccountRef',
      qb.DepositToAccountRef?.value
    );
  }

  const depositLines = (qb.Line || []).filter((line) => {
    const linkedTransactions = line.LinkedTxn || [];

    return (
      line.DetailType === 'DepositLineDetail' ||
      Boolean(line.DepositLineDetail) ||
      linkedTransactions.some((txn) => txn.TxnType === 'Payment')
    );
  });

  if (!depositLines.length) {
    return quarantine(
      'Deposit',
      qb,
      'NO_DEPOSIT_LINES',
      'Deposit contains no usable account or linked-payment lines.',
      'Line',
      ''
    );
  }

  const undepositedQboId = clean(
    config.undeposited_funds_qbo_account_id || '59'
  );

  const undepositedZohoId = clean(
    maps.account_by_qbo_id?.[undepositedQboId]
  );

  const resolvedLines = [];

  for (let index = 0; index < depositLines.length; index++) {
    const line = depositLines[index];
    const detail = line.DepositLineDetail || {};
    const linkedTransactions = line.LinkedTxn || [];

    const linkedPayment = linkedTransactions.find(
      (txn) => txn.TxnType === 'Payment'
    );

    let fromId = '';
    let sourceType = '';
    let sourceQboAccountId = '';

    if (detail.AccountRef?.value) {
      sourceQboAccountId = clean(detail.AccountRef.value);

      fromId = resolveId(
        maps,
        'account_by_qbo_id',
        detail.AccountRef
      );

      sourceType = 'account';
    } else if (linkedPayment) {
      fromId = undepositedZohoId;
      sourceQboAccountId = undepositedQboId;
      sourceType = 'linked_payment';
    }

    if (!fromId) {
      return quarantine(
        'Deposit',
        qb,
        linkedPayment
          ? 'UNDEPOSITED_FUNDS_UNMAPPED'
          : 'DEPOSIT_SOURCE_UNMAPPED',
        linkedPayment
          ? 'Linked customer payment deposit requires the Zoho Undeposited Funds account mapping.'
          : 'Deposit source account is not mapped.',
        linkedPayment
          ? 'undeposited_funds_qbo_account_id'
          : 'Line.DepositLineDetail.AccountRef',
        linkedPayment
          ? undepositedQboId
          : detail.AccountRef?.value,
        {
          source_line_id: clean(line.Id),
          linked_payment_qbo_id: clean(linkedPayment?.TxnId)
        }
      );
    }

    const amount = round(line.Amount, 2);

    if (Math.abs(amount) <= 0) {
      return quarantine(
        'Deposit',
        qb,
        'INVALID_DEPOSIT_LINE_AMOUNT',
        'Deposit line amount must be non-zero.',
        'Line.Amount',
        line.Amount,
        {
          source_line_id: clean(line.Id)
        }
      );
    }

    resolvedLines.push({
      fromId,
      sourceType,
      sourceQboAccountId,
      amount,
      description:
        clean(line.Description) ||
        (
          linkedPayment
            ? `QBO Payment ${clean(linkedPayment.TxnId)} deposited`
            : `QBO Deposit ${clean(qb.Id)}`
        ),
      linkedPaymentQboId: clean(linkedPayment?.TxnId)
    });
  }

  const sourceTotal = round(
    resolvedLines.reduce(
      (sum, line) => sum + num(line.amount),
      0
    ),
    2
  );

  const qboTotal = round(qb.TotalAmt, 2);
  const tolerance = num(config.amount_tolerance || 0.01);

  if (Math.abs(sourceTotal - qboTotal) > tolerance) {
    return quarantine(
      'Deposit',
      qb,
      'DEPOSIT_TOTAL_MISMATCH',
      'Deposit line total does not match QuickBooks TotalAmt.',
      'TotalAmt',
      qb.TotalAmt,
      {
        calculated_line_total: sourceTotal,
        difference: round(qboTotal - sourceTotal, 2)
      }
    );
  }

  if (resolvedLines.length === 1) {
    const line = resolvedLines[0];

    const sourceMeta =
      maps.account_meta_by_qbo_id?.[
        clean(line.sourceQboAccountId)
      ] || {};

    const destinationMeta =
      maps.account_meta_by_qbo_id?.[
        clean(qb.DepositToAccountRef?.value)
      ] || {};

    const sourceAccountType = clean(
      sourceMeta.zoho_account_type
    ).toLowerCase();

    const destinationAccountType = clean(
      destinationMeta.zoho_account_type
    ).toLowerCase();

    const expenseTypes = new Set([
      'expense',
      'other_expense',
      'cost_of_goods_sold'
    ]);

    const bankLikeTypes = new Set([
      'bank',
      'cash',
      'payment_clearing_account'
    ]);

    let transactionType = 'deposit';

    if (line.sourceType === 'linked_payment') {
      transactionType = 'transfer_fund';
    } else if (expenseTypes.has(sourceAccountType)) {
      // Zoho uses `refund` for Money In to a credit-card account.
      // This debits/reduces the credit-card liability and credits the expense account.
      transactionType =
        destinationAccountType === 'credit_card'
          ? 'refund'
          : 'expense_refund';
    } else if (bankLikeTypes.has(sourceAccountType)) {
      transactionType =
        destinationAccountType === 'credit_card'
          ? 'card_payment'
          : 'transfer_fund';
    }

    // Zoho banktransactions does not accept a credit-card -> bank deposit.
    // Let that combination fall through to the balanced journal builder below.
    const requiresJournal =
      clean(qb.Id) === '225' ||
      (
        sourceAccountType === 'credit_card' &&
        bankLikeTypes.has(destinationAccountType)
      );

    if (!requiresJournal) {
      return ready(
        config,
        'Deposit',
        qb,
        'banktransactions',
        {
          from_account_id: line.fromId,
          to_account_id: toId,
          transaction_type: transactionType,
          amount: Math.abs(qboTotal),
          date: clean(qb.TxnDate),
          payment_mode:
            ['expense_refund', 'refund'].includes(transactionType)
              ? 'others'
              : undefined,
          reference_number: key,
          description:
            clean(qb.PrivateNote) ||
            (
              line.sourceType === 'linked_payment'
                ? `QBO linked payment ${line.linkedPaymentQboId}: Undeposited Funds transferred to bank`
                : line.description
            )
        }
      );
    }
  }

  const journalLines = [];

  journalLines.push({
    account_id: toId,
    debit_or_credit: qboTotal >= 0 ? 'debit' : 'credit',
    amount: Math.abs(qboTotal),
    description:
      clean(qb.PrivateNote) ||
      `QBO Deposit ${clean(qb.Id)} destination`
  });

  for (const line of resolvedLines) {
    journalLines.push({
      account_id: line.fromId,
      debit_or_credit: line.amount >= 0 ? 'credit' : 'debit',
      amount: Math.abs(line.amount),
      description: line.description
    });
  }

  const journalDebit = round(
    journalLines
      .filter((line) => line.debit_or_credit === 'debit')
      .reduce((sum, line) => sum + num(line.amount), 0),
    2
  );

  const journalCredit = round(
    journalLines
      .filter((line) => line.debit_or_credit === 'credit')
      .reduce((sum, line) => sum + num(line.amount), 0),
    2
  );

  if (Math.abs(journalDebit - journalCredit) > tolerance) {
    return quarantine(
      'Deposit',
      qb,
      'UNBALANCED_DEPOSIT_JOURNAL',
      'Generated deposit journal debit and credit totals are different.',
      'Line.Amount',
      '',
      {
        debit: journalDebit,
        credit: journalCredit
      }
    );
  }

  return ready(
    config,
    'Deposit',
    qb,
    'journals',
    {
      journal_date: clean(qb.TxnDate),
      reference_number: key,
      notes:
        clean(qb.PrivateNote) ||
        `Multi-line QuickBooks Deposit ${clean(qb.Id)}`,
      line_items: journalLines
    }
  );
}

function buildJournal(config, maps, qb) {
  const lines = [];
  const descriptionNotes = [];

  let debit = 0;
  let credit = 0;

  const tolerance = num(config.amount_tolerance || 0.01);

  // Fallback contacts
  const defaultCustomerId = clean(
    config.default_migration_customer_id ||
    Object.values(maps.customer_by_qbo_id || {})[0] ||
    ''
  );

  const defaultVendorId = clean(
    config.default_migration_vendor_id ||
    Object.values(maps.vendor_by_qbo_id || {})[0] ||
    ''
  );

  for (const line of qb.Line || []) {
    if (line.DetailType === 'DescriptionOnly') {
      const note = clean(line.Description);
      if (note) descriptionNotes.push(note);
      continue;
    }

    if (
      line.DetailType !== 'JournalEntryLineDetail' &&
      !line.JournalEntryLineDetail
    ) {
      return quarantine(
        'JournalEntry',
        qb,
        'UNSUPPORTED_JOURNAL_LINE',
        'Journal contains an unsupported non-accounting line.',
        'Line.DetailType',
        line.DetailType,
        {
          source_line_id: clean(line.Id)
        }
      );
    }

    const detail = line.JournalEntryLineDetail || {};

    const accountId = resolveId(
      maps,
      'account_by_qbo_id',
      detail.AccountRef
    );

    if (!accountId) {
      return quarantine(
        'JournalEntry',
        qb,
        'JOURNAL_ACCOUNT_UNMAPPED',
        'Journal line account is not mapped.',
        'AccountRef',
        detail.AccountRef?.value,
        {
          source_line_id: clean(line.Id),
          qbo_account_name: clean(detail.AccountRef?.name)
        }
      );
    }

    const side = clean(detail.PostingType).toLowerCase();
    const amount = Math.abs(round(line.Amount, 2));

    if (side !== 'debit' && side !== 'credit') {
      return quarantine(
        'JournalEntry',
        qb,
        'INVALID_POSTING_TYPE',
        'Journal line posting type is not Debit or Credit.',
        'PostingType',
        detail.PostingType,
        {
          source_line_id: clean(line.Id)
        }
      );
    }

    if (amount <= tolerance) {
      continue;
    }

    if (side === 'debit') {
      debit += amount;
    } else {
      credit += amount;
    }

    // AR vs AP Check
    const accountMeta = maps.account_meta_by_qbo_id?.[clean(detail.AccountRef?.value)] || {};
    const accountType = clean(accountMeta.zoho_account_type).toLowerCase();

    const isAr = accountType === 'accounts_receivable';
    const isAp = accountType === 'accounts_payable';

    const entityRef = detail.Entity?.EntityRef;
    const entityType = clean(detail.Entity?.Type).toLowerCase();
    let contactId;

    if (isAr) {
      contactId = resolveId(maps, 'customer_by_qbo_id', entityRef);
      if (!contactId) {
        return quarantine('JournalEntry', qb, 'AR_CUSTOMER_UNMAPPED',
          'Accounts Receivable journal line requires the exact mapped QuickBooks customer.',
          'JournalEntryLineDetail.Entity', entityRef?.value,
          { source_line_id: clean(line.Id), entity_type: entityType });
      }
    } else if (isAp) {
      contactId = resolveId(maps, 'vendor_by_qbo_id', entityRef);
      if (!contactId) {
        return quarantine('JournalEntry', qb, 'AP_VENDOR_UNMAPPED',
          'Accounts Payable journal line requires the exact mapped QuickBooks vendor.',
          'JournalEntryLineDetail.Entity', entityRef?.value,
          { source_line_id: clean(line.Id), entity_type: entityType });
      }
    }

    lines.push(compact({
      account_id: accountId,
      debit_or_credit: side,
      amount,
      description: clean(line.Description),
      customer_id: contactId
    }));
  }

  if (lines.length < 2) {
    return quarantine(
      'JournalEntry',
      qb,
      'NO_POSTABLE_JOURNAL_LINES',
      'Journal does not contain at least two non-zero accounting lines.',
      'Line',
      ''
    );
  }

  debit = round(debit, 2);
  credit = round(credit, 2);

  if (Math.abs(debit - credit) > tolerance) {
    return quarantine(
      'JournalEntry',
      qb,
      'UNBALANCED_JOURNAL',
      'Journal debit and credit totals are not equal.',
      'Line.Amount',
      '',
      {
        debit,
        credit,
        difference: round(debit - credit, 2)
      }
    );
  }

  const notes = [
    clean(qb.PrivateNote),
    ...descriptionNotes
  ].filter(Boolean).join(' | ');

  return ready(
    config,
    'JournalEntry',
    qb,
    'journals',
    {
      journal_date: clean(qb.TxnDate),
      reference_number: sourceKey('JournalEntry', qb.Id),
      notes: notes || 'Migrated from QuickBooks',
      line_items: lines
    }
  );
}


function buildCreditMemo(config, maps, qb) {
  const linked = (qb.LinkedTxn || []).filter((txn) => txn.TxnType === 'Invoice');
  if (linked.length) {
    return quarantine('CreditMemo', qb, 'CREDIT_ALLOCATION_REQUIRES_TWO_STEP',
      'Credit memo is linked to an invoice. Create the credit note first, then apply it with the Zoho credit-note invoices endpoint.',
      'LinkedTxn', linked.map((txn) => txn.TxnId).join(','));
  }
  const customerId = resolveId(maps, 'customer_by_qbo_id', qb.CustomerRef);
  if (!customerId) return quarantine('CreditMemo', qb, 'CUSTOMER_UNMAPPED',
    'Credit memo customer is not mapped.', 'CustomerRef', qb.CustomerRef?.value);
  const built = salesLines(config, maps, qb, 'CreditMemo');
  if (built.error) return built.error;
  if (!built.lines.length) return quarantine('CreditMemo', qb, 'NO_POSTABLE_LINES',
    'Credit memo contains no supported lines.', 'Line', '');
  return ready(config, 'CreditMemo', qb, 'creditnotes', {
    customer_id: customerId,
    creditnote_number: clean(qb.DocNumber) || ('QB-CM-' + qb.Id),
    reference_number: sourceKey('CreditMemo', qb.Id),
    date: clean(qb.TxnDate),
    exchange_rate: qb.ExchangeRate === undefined ? undefined : num(qb.ExchangeRate),
    line_items: built.lines,
    notes: clean(qb.CustomerMemo?.value || qb.PrivateNote) || 'Migrated from QuickBooks'
  });
}

function buildVendorCredit(config, maps, qb) {
  const linked = (qb.LinkedTxn || []).filter((txn) => txn.TxnType === 'Bill');
  if (linked.length) {
    return quarantine('VendorCredit', qb, 'VENDOR_CREDIT_ALLOCATION_REQUIRES_TWO_STEP',
      'Vendor credit is linked to a bill. Create the vendor credit first, then apply it with the Zoho vendor-credit bills endpoint.',
      'LinkedTxn', linked.map((txn) => txn.TxnId).join(','));
  }
  const vendorId = resolveId(maps, 'vendor_by_qbo_id', qb.VendorRef);
  if (!vendorId) return quarantine('VendorCredit', qb, 'VENDOR_UNMAPPED',
    'Vendor credit vendor is not mapped.', 'VendorRef', qb.VendorRef?.value);
  const built = purchaseLines(config, maps, qb, 'VendorCredit');
  if (built.error) return built.error;
  if (!built.lines.length) return quarantine('VendorCredit', qb, 'NO_POSTABLE_LINES',
    'Vendor credit contains no supported lines.', 'Line', '');
  return ready(config, 'VendorCredit', qb, 'vendorcredits', {
    vendor_id: vendorId,
    vendor_credit_number: clean(qb.DocNumber) || ('QB-VC-' + qb.Id),
    reference_number: sourceKey('VendorCredit', qb.Id),
    date: clean(qb.TxnDate),
    exchange_rate: qb.ExchangeRate === undefined ? undefined : num(qb.ExchangeRate),
    line_items: built.lines,
    notes: clean(qb.PrivateNote) || 'Migrated from QuickBooks'
  });
}

function buildSalesReceipt(config, maps, qb) {
  const customerId = resolveId(maps, 'customer_by_qbo_id', qb.CustomerRef);
  if (!customerId) return quarantine('SalesReceipt', qb, 'CUSTOMER_UNMAPPED',
    'Sales receipt customer is not mapped.', 'CustomerRef', qb.CustomerRef?.value);
  const depositQboId = clean(qb.DepositToAccountRef?.value);
  const undepositedQboId = clean(config.undeposited_funds_qbo_account_id || '');
  if (depositQboId && undepositedQboId && depositQboId !== undepositedQboId) {
    return quarantine('SalesReceipt', qb, 'SALES_RECEIPT_DEPOSIT_REQUIRES_TWO_STEP',
      'Zoho sales-receipt create API does not accept a deposit-account ID. Direct-to-bank QBO receipt needs a reviewed follow-up bank transfer.',
      'DepositToAccountRef', depositQboId);
  }
  const built = salesLines(config, maps, qb, 'SalesReceipt');
  if (built.error) return built.error;
  if (!built.lines.length) return quarantine('SalesReceipt', qb, 'NO_POSTABLE_LINES',
    'Sales receipt contains no supported lines.', 'Line', '');
  const key = sourceKey('SalesReceipt', qb.Id);
  return ready(config, 'SalesReceipt', qb, 'salesreceipts', {
    customer_id: customerId,
    receipt_number: clean(qb.DocNumber) || ('QB-SR-' + qb.Id),
    date: clean(qb.TxnDate),
    payment_mode: paymentMode(qb),
    line_items: built.lines,
    notes: [key, clean(qb.CustomerMemo?.value || qb.PrivateNote)].filter(Boolean).join(' | ')
  });
}

function buildRefundReceipt(config, maps, qb) {
  return quarantine('RefundReceipt', qb, 'REFUND_RECEIPT_REQUIRES_TWO_STEP',
    'QBO RefundReceipt must be represented by a Zoho credit note plus a credit-note refund. A single create call would change the ledger incorrectly.',
    'source_entity', 'RefundReceipt');
}

function sourceOwnerPhase(entity, maps, qb) {
  const metaFor = (ref) => maps.account_meta_by_qbo_id?.[clean(ref?.value)] || {};
  const typeFor = (ref) => clean(metaFor(ref).zoho_account_type).toLowerCase();
  const bankLike = new Set(['bank', 'cash', 'payment_clearing_account']);
  const fundingTypes = new Set([...bankLike, 'credit_card']);
  const balanceSheet = new Set([
    'bank', 'cash', 'payment_clearing_account', 'credit_card',
    'accounts_receivable', 'accounts_payable',
    'other_current_asset', 'fixed_asset', 'other_asset', 'stock',
    'non_current_asset', 'intangible_asset', 'deferred_tax_asset',
    'capital_work_in_progress', 'intangible_assets_under_development',
    'other_current_liability', 'long_term_liability',
    'non_current_liability', 'other_liability', 'deferred_tax_liability',
    'equity'
  ]);
  const expenseTypes = new Set(['expense', 'other_expense', 'cost_of_goods_sold']);

  const direct = {
    Account: 'accounts', Customer: 'customers', Vendor: 'vendors', Item: 'items',
    Invoice: 'invoices', Payment: 'invoice_payments', Bill: 'bills',
    BillPayment: 'bill_payments', JournalEntry: 'journals'
  };
  if (direct[entity]) return direct[entity];

  if (entity === 'Purchase') {
    const sourceType = typeFor(qb.AccountRef);
    const qboCreditFlag = qb.Credit === true || clean(qb.Credit).toLowerCase() === 'true';
    const qboPaymentType = clean(qb.PaymentType).toLowerCase();

    // Credit Card Credit is a Purchase with Credit=true. Its AccountRef is the
    // credit-card account itself, so no bank account participates in the refund.
    if (qboCreditFlag && qboPaymentType === 'creditcard' && sourceType === 'credit_card') {
      return 'expense_refunds';
    }

    const targetTypes = (qb.Line || [])
      .filter((line) => Math.abs(num(line.Amount)) > num((qb.config || {}).amount_tolerance || 0.01))
      .map((line) => {
        if (line.DetailType === 'AccountBasedExpenseLineDetail') {
          return typeFor(line.AccountBasedExpenseLineDetail?.AccountRef);
        }
        if (line.DetailType === 'ItemBasedExpenseLineDetail') return 'item_expense';
        return 'unsupported';
      });
    if (bankLike.has(sourceType) && targetTypes.includes('credit_card')) {
      return 'credit_card_repayments';
    }
    if (fundingTypes.has(sourceType) && targetTypes.some((type) =>
      balanceSheet.has(type) && type !== sourceType && !bankLike.has(type))) {
      return 'bank_transactions';
    }
    return 'expenses';
  }

  if (entity === 'Transfer') {
    const fromType = typeFor(qb.FromAccountRef);
    const toType = typeFor(qb.ToAccountRef);
    if (bankLike.has(fromType) && toType === 'credit_card') return 'credit_card_repayments';
    return 'bank_transactions';
  }

  if (entity === 'Deposit') {
    const destinationType = typeFor(qb.DepositToAccountRef);
    const nonZero = (qb.Line || []).filter((line) => Math.abs(num(line.Amount)) > 0);
    const hasLinkedPayment = nonZero.some((line) =>
      (line.LinkedTxn || []).some((txn) => txn.TxnType === 'Payment'));
    const sourceTypes = nonZero.map((line) => typeFor(line.DepositLineDetail?.AccountRef)).filter(Boolean);
    if (!hasLinkedPayment && sourceTypes.length === 1 && expenseTypes.has(sourceTypes[0])) {
      return 'expense_refunds';
    }
    if (!hasLinkedPayment && sourceTypes.length === 1 && bankLike.has(sourceTypes[0]) && destinationType === 'credit_card') {
      return 'credit_card_repayments';
    }
    return 'bank_transactions';
  }

  return 'unsupported';
}

const builders = {
  Account: buildAccount,
  Customer: (config, maps, qb) => buildContact(config, maps, qb, 'Customer'),
  Vendor: (config, maps, qb) => buildContact(config, maps, qb, 'Vendor'),
  Item: buildItem,
  Invoice: buildInvoice,
  Payment: buildCustomerPayment,
  Bill: buildBill,
  BillPayment: buildVendorPayment,
  Purchase: buildExpense,
  Transfer: buildTransfer,
  Deposit: buildDeposit,
  JournalEntry: buildJournal,
  CreditMemo: buildCreditMemo,
  VendorCredit: buildVendorCredit,
  SalesReceipt: buildSalesReceipt,
  RefundReceipt: buildRefundReceipt
};

const output = [];
for (const item of input) {
  const { config = {}, maps = {}, source_entity: entity, source: qb = {} } = item.json;
  if (!clean(config.zoho_organization_id)) {
    output.push(quarantine(entity || 'Unknown', qb, 'ZOHO_ORG_ID_MISSING',
      'A single target Zoho organisation ID is required.', 'zoho_organization_id', ''));
    continue;
  }
  if (!clean(qb.Id)) {
    output.push(quarantine(entity || 'Unknown', qb, 'QBO_ID_MISSING',
      'Source entity has no QuickBooks ID.', 'Id', ''));
    continue;
  }
  // Purchase 3483 contains both expense and balance-sheet lines.
  // Do not migrate it as a bank transaction; handle it later as a manual journal.
  const deferredJournalPurchaseIds = new Set([
    '3483',
  ]);

  if (
    clean(config.phase) === 'bank_transactions' &&
    entity === 'Purchase' &&
    deferredJournalPurchaseIds.has(clean(qb.Id))
  ) {
    output.push({
      json: {
        outcome: 'skipped_other_phase',
        source_entity: entity,
        source_id: clean(qb.Id),
        source_doc_number: clean(qb.DocNumber),
        source_key: sourceKey(entity, qb.Id),
        owner_phase: 'journals',
        current_phase: clean(config.phase),
        skip_reason: 'Mixed expense and balance-sheet purchase deferred for manual journal entry.',
      },
    });
    continue;
  }

  const ownerPhase = sourceOwnerPhase(entity, maps, qb);
  if (config.strict_phase_ownership === true && ownerPhase !== config.phase) {
    output.push({ json: {
      outcome: 'skipped_other_phase',
      source_entity: entity,
      source_id: clean(qb.Id),
      source_doc_number: clean(qb.DocNumber),
      source_key: sourceKey(entity, qb.Id),
      owner_phase: ownerPhase,
      current_phase: clean(config.phase)
    }});
    continue;
  }
  const existingTarget = clean(maps.existing_by_source_key?.[sourceKey(entity, qb.Id)]);
  // Existing source references must be skipped before rebuilding. This prevents
  // successful records from being treated as wrong-module repairs on reruns.
  const classifyExistingBeforeSkip = false;
  if (config.repair_existing_only !== false && existingTarget && !classifyExistingBeforeSkip) {
    output.push({ json: {
      outcome: 'skipped_existing', source_entity: entity, source_id: clean(qb.Id),
      source_doc_number: clean(qb.DocNumber), source_key: sourceKey(entity, qb.Id),
      target_id: existingTarget
    }});
    continue;
  }
  const builder = builders[entity];
  if (!builder) {
    output.push(quarantine(entity || 'Unknown', qb, 'UNSUPPORTED_ENTITY_NEEDS_MODULE_TRANSFORMER',
      'This source entity requires an explicit, reviewed Zoho module transformer.', 'source_entity', entity));
    continue;
  }
  try {
    const built = builder(config, maps, qb);
    if (config.repair_existing_only !== false && existingTarget && built?.json?.outcome === 'ready') {
      const key = sourceKey(entity, qb.Id);
      const intendedModule = clean(built.json.endpoint).split('/').filter(Boolean).at(-1) || '';
      const currentModule = clean(maps.existing_module_by_source_key?.[key]);
      if (currentModule && intendedModule && currentModule !== intendedModule) {
        output.push(quarantine(entity, qb, 'EXISTING_SOURCE_KEY_WRONG_MODULE',
          'This QuickBooks transaction already exists in a different Zoho module. Review and remove/void the wrong target before repair.',
          'source_key', key, {
            target_id: existingTarget,
            existing_zoho_module: currentModule,
            intended_zoho_module: intendedModule,
            migration_kind: built.json.migration_kind || ''
          }));
      } else {
        output.push({ json: {
          outcome: 'skipped_existing', source_entity: entity, source_id: clean(qb.Id),
          source_doc_number: clean(qb.DocNumber), source_key: key,
          target_id: existingTarget, target_module: currentModule || intendedModule
        }});
      }
    } else {
      output.push(built);
    }
  } catch (error) {
    output.push(quarantine(entity, qb, 'TRANSFORM_EXCEPTION', error.message || String(error), '', ''));
  }
}

return output;

const all = $('Strict Payload Builder4').all().map(i => i.json);
const config = $('Validate Config4').first().json;
const counts = all.reduce((a, r) => { a[r.outcome] = (a[r.outcome] || 0) + 1; return a; }, {});
const quarantined = all.filter(r => r.outcome === 'quarantine');
const ready = all.filter(r => r.outcome === 'ready');
const maxLive = Math.max(1, Number(config.max_live_records_per_run || 700));
const quotaBlocked = !config.dry_run && ready.length > maxLive;
const strictBlocked = Boolean(config.stop_on_any_unmapped_value && quarantined.length > 0);
return [{ json: {
  run_mode: config.dry_run ? 'dry_run' : ((strictBlocked || quotaBlocked) ? 'live_blocked' : 'live'),
  phase: config.phase,
  counts,
  ready_count: ready.length,
  max_live_records_per_run: maxLive,
  quota_blocked: quotaBlocked,
  can_go_live: quarantined.length === 0 && ready.length <= maxLive,
  live_blocked: strictBlocked || quotaBlocked,
  next_action: quarantined.length ? 'Fix quarantines.' : (ready.length > maxLive ? 'Reduce date range so ready_count is within max_live_records_per_run.' : 'Safe to set dry_run=false.'),
  quarantine_sample: quarantined.slice(0, 50),
  ready_sample: ready.slice(0, 20).map(r => ({ source_key: r.source_key, endpoint: r.endpoint, migration_kind: r.migration_kind || '' }))
} }];

const inputs = $input.all();
const clean = (value) => String(value ?? '').trim();
const idKeys = [
  'account_id', 'contact_id', 'item_id', 'invoice_id', 'payment_id', 'bill_id',
  'vendorpayment_id', 'vendor_payment_id', 'expense_id', 'bank_transaction_id',
  'transaction_id', 'journal_id', 'creditnote_id', 'vendor_credit_id', 'sales_receipt_id'
];
const findTargetId = (value) => {
  if (!value || typeof value !== 'object') return '';
  for (const key of idKeys) if (clean(value[key])) return clean(value[key]);
  for (const child of Object.values(value)) {
    if (child && typeof child === 'object') {
      const found = findTargetId(child);
      if (found) return found;
    }
  }
  return '';
};

return inputs.map((item) => {
  const wrapper = item.json || {};
  const body = wrapper.body || wrapper;
  let request = {};
  try { request = $('Zoho Write Rate Limit Loop5').item.json || {}; } catch (_) {}
  const code = body.code === undefined ? null : Number(body.code);
  const statusCode = Number(wrapper.statusCode || 0);
  const ok = code === 0 || (code === null && statusCode >= 200 && statusCode < 300);
  return { json: {
    run_id: $execution.id,
    phase: clean(request.config?.phase || request.phase || $('Validate Config4').first().json.phase),
    source_entity: clean(request.source_entity),
    source_id: clean(request.source_id),
    source_doc_number: clean(request.source_doc_number),
    source_key: clean(request.source_key),
    target_module: clean(request.endpoint).split('/').filter(Boolean).at(-1) || '',
    target_id: findTargetId(body),
    outcome: ok ? 'created' : 'failed',
    error_code: ok ? '' : clean(body.code ?? wrapper.statusCode ?? 'HTTP_ERROR'),
    error_message: ok ? '' : clean(body.message || body.error?.message || wrapper.error || 'Zoho returned an unknown response'),
    raw_response: JSON.stringify(body),
    occurred_at: new Date().toISOString()
  }};
});

const all = $('Strict Payload Builder4').all().map(i => i.json);
const config = $('Validate Config4').first().json;
const counts = all.reduce((acc, row) => {
  const key = row.outcome || 'unknown';
  acc[key] = (acc[key] || 0) + 1;
  return acc;
}, {});
const quarantined = all.filter(row => row.outcome === 'quarantine');
const creditCardRepayments = all.filter(row => row.migration_kind === 'credit_card_repayment');
const blockedByStrictMode = Boolean(config.stop_on_any_unmapped_value && quarantined.length);
return [{ json: {
  run_mode: config.dry_run ? 'dry_run' : (blockedByStrictMode ? 'live_blocked' : 'live'),
  phase: config.phase,
  counts,
  can_go_live: quarantined.length === 0,
  live_blocked: blockedByStrictMode,
  credit_card_repayments_detected: creditCardRepayments.length,
  credit_card_repayment_sample: creditCardRepayments.slice(0, 25).map(row => ({
    source_entity: row.source_entity,
    source_id: row.source_id,
    source_key: row.source_key,
    amount: row.payload?.amount,
    date: row.payload?.date,
    from_account_id: row.payload?.from_account_id,
    to_account_id: row.payload?.to_account_id
  })),
  next_action: quarantined.length ? 'Fix every quarantine, then run dry_run again.' : (config.dry_run ? 'Set dry_run=false and run from Manual Trigger.' : 'Live migration completed.'),
  quarantine_sample: quarantined.slice(0, 50)
}}];

const response = $json.body || $json;
if (!response.access_token) {
  throw new Error('QuickBooks token refresh failed: ' + JSON.stringify(response));
}

const sourceConfig = $('Validate Config4').first().json;
return [{
  json: {
    ...sourceConfig,
    qbo_access_token: response.access_token,
    qbo_refresh_token_next: response.refresh_token || ''
  }
}];

const clientId = String($json.qbo_client_id || '').trim();
const clientSecret = String($json.qbo_client_secret || '').trim();
const refreshToken = String($json.qbo_refresh_token || '').trim();

if (!clientId || !clientSecret || !refreshToken) {
  throw new Error('QuickBooks Client ID, Client Secret and Refresh Token are required.');
}

const qboBasicAuthorization = 'Basic ' + Buffer
  .from(clientId + ':' + clientSecret, 'utf8')
  .toString('base64');

return [{
  json: {
    qbo_basic_authorization: qboBasicAuthorization,
    qbo_refresh_token: refreshToken
  }
}];

const inputItems = $input.all();
const sourceRows = [];
let maps = {};

for (const item of inputItems) {
  const json = item.json || {};
  if (json.maps && Object.keys(json.maps).length) maps = json.maps;
  if (Array.isArray(json.source_rows)) {
    sourceRows.push(...json.source_rows);
  } else if (json.source_entity && json.source) {
    sourceRows.push(json);
  }
}

const clean = value => String(value ?? '').trim();
const supportedEntities = new Set([
  'Account','Customer','Vendor','Item','Invoice','Payment','Bill','BillPayment',
  'Purchase','Transfer','Deposit','JournalEntry','CreditMemo','VendorCredit',
  'SalesReceipt','RefundReceipt'
]);
const existingBySourceKey = maps.existing_by_source_key || {};
const summary = {};
const missing = [];
const seen = new Set();

for (const row of sourceRows) {
  const entity = clean(row.source_entity);
  const source = row.source || {};
  const sourceId = clean(source.Id);
  if (!supportedEntities.has(entity) || !sourceId) continue;

  const sourceKey = `QBO:${entity}:${sourceId}`;
  if (seen.has(sourceKey)) continue;
  seen.add(sourceKey);

  if (!summary[entity]) {
    summary[entity] = { qbo_count: 0, migrated_count: 0, missing_count: 0 };
  }
  summary[entity].qbo_count++;

  const targetId = clean(existingBySourceKey[sourceKey]);
  if (targetId) {
    summary[entity].migrated_count++;
    continue;
  }

  summary[entity].missing_count++;
  missing.push({
    source_entity: entity,
    source_id: sourceId,
    source_doc_number: clean(source.DocNumber),
    source_key: sourceKey,
    txn_date: clean(source.TxnDate || source.MetaData?.CreateTime),
    amount: Number(source.TotalAmt ?? source.Amount ?? source.Balance ?? 0),
    message: 'No matching QBO source reference was found in the Zoho snapshots.'
  });
}

const totals = Object.values(summary).reduce((acc, value) => {
  acc.qbo += value.qbo_count;
  acc.migrated += value.migrated_count;
  acc.missing += value.missing_count;
  return acc;
}, { qbo: 0, migrated: 0, missing: 0 });

return [
  { json: {
    audit_type: 'OVERALL_MIGRATION_SUMMARY',
    audit_read_only: true,
    total_qbo_records: totals.qbo,
    total_migrated_records: totals.migrated,
    total_missing_records: totals.missing,
    migration_complete_by_reference: totals.missing === 0,
    entity_summary: summary,
    warning: 'Reference completeness does not prove ledger balances; reconcile Trial Balance separately.'
  }},
  ...missing.map((record, index) => ({ json: {
    audit_type: 'MISSING_RECORD',
    missing_row_number: index + 1,
    ...record
  }}))
];

const wanted = new Set([
  'Account:30',
  'Account:59',
  'Purchase:4172',
  'Purchase:4165',
  'Purchase:2320',
]);

const results = [];

for (const item of $input.all()) {
  const bundle = item.json || {};

  const rows = Array.isArray(bundle.source_rows)
    ? bundle.source_rows
    : [bundle];

  for (const row of rows) {
    const entity = String(row.source_entity || '').trim();
    const source = row.source || {};
    const id = String(source.Id || '').trim();
    const key = `${entity}:${id}`;

    if (!wanted.has(key)) continue;

    results.push({
      json: {
        inspect_key: key,
        source_entity: entity,
        source_id: id,
        source,
      },
    });
  }
}

if (!results.length) {
  return [{
    json: {
      outcome: 'not_found',
      message: 'Requested missing records were not present in the overall audit source rows.',
    },
  }];
}

return results;
